(function(global){
'use strict';
const RA=global.RA=global.RA||{};
const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('weight','Weight comes from Old English gewiht, related to weigh; it can mean heaviness, a heavy object used for holding or measuring, or importance and influence.',[C('weight.s1','measurement','The suitcase’s weight was 18 kilograms, so it stayed below the airline limit.','行李箱重18千克，因此没有超过航空公司的限重。','body/luggage weight; weigh something','名词，指人或物有多重。','Kilograms measure how heavy the suitcase is.','重量'),C('weight.s2','tools','She put a small weight on the papers so the open window would not blow them away.','她在文件上压了一块小重物，免得开着的窗户把纸吹走。','paper weight; add a weight','名词，指因重量而用于压住或测量物品的物体。','The object holds the papers down.','重物'),C('weight.s3','influence','The judge gave greater weight to the witness who had seen the event directly.','法官更重视亲眼目睹事件的证人证词。','give weight to an argument; political weight','比喻指重要性或影响力。','The testimony has greater influence on the decision.','重要性')],M('The judge gave the rumor more weight because it came from nobody and had no evidence.','The judge gave the firsthand testimony more weight because it was supported by evidence.','A baseless rumor should not carry more evidential weight.','meaning'),[Q(1,'What did 18 kilograms describe?','The suitcase’s heaviness','The suitcase’s age','The suitcase’s color','Sense 1 is heaviness measured in units.','context'),Q(2,'Why place a weight on the papers?','To keep them from blowing away','To tell how old they were','To make them easier to read aloud','Sense 2 is a heavy object used to hold something down.','context'),Q(3,'Why did the judge give the testimony greater weight?','It could influence the decision','It had more kilograms','It was written on heavier paper','Sense 3 means importance or influence.','context'),Q(1,'Which phrase means “treat an argument as important”?','give weight to an argument','weigh an argument down','weight an argument at','The idiom uses weight figuratively for importance.','collocation')]);
P('weightily','Weightily is weighty + -ly and means in a heavy manner or with solemn importance.',C('weightily.s1','manner','The chair addressed the safety issue weightily, pausing to stress its serious consequences.','主席郑重地谈到安全问题，停顿着强调其严重后果。','speak/write weightily; weightily important','副词，指语气沉重或显得非常重要。','The careful delivery gives the issue solemn importance.','郑重地'),M('She spoke weightily about the emergency while joking and dismissing every risk.','She spoke casually about the emergency while joking and dismissing every risk.','A joking, dismissive manner is not weighty or solemn.','meaning'),[Q(1,'How did the chair address the safety issue?','With solemn emphasis','As a trivial joke','Without mentioning consequences','Weightily describes a serious, important manner.','context'),Q(1,'If a speech is delivered weightily, it sounds…','grave and significant','light and careless','physically heavy','The adverb describes manner, not physical mass.','meaning'),Q(1,'Which sentence uses weightily naturally?','The report treated the risk weightily.','The report was weightily heavier than a truck.','She weightily to the station.','Weightily modifies how a matter is treated.','grammar'),Q(1,'Weightily is formed from…','weighty + -ly','weight + -less','weigh + -ment','The adverb uses the adjective weighty and the suffix -ly.','word-formation')]);
P('weightlessness','Weightlessness is formed from weight + -less + -ness and names a condition in which gravity seems to exert no weight, so objects float.',C('weightlessness.s1','spaceflight','Inside the orbiting spacecraft, the astronauts experienced weightlessness as tools floated beside them.','在轨道飞船内，宇航员体验到失重，工具漂浮在他们身旁。','experience weightlessness; effects of weightlessness','名词，指物体似乎没有重量、会漂浮的状态。','The floating tools show apparent weightlessness.','失重'),M('The astronauts experienced weightlessness because every tool was firmly pressed against the floor by gravity.','The astronauts experienced weightlessness as tools floated freely around the cabin.','Objects pressed to the floor are not displaying weightlessness.','meaning'),[Q(1,'What showed weightlessness inside the spacecraft?','Tools floated beside the astronauts','Every tool stayed fixed to the floor','The spacecraft sank into the ocean','Weightlessness is illustrated by floating objects.','context'),Q(1,'Weightlessness is a condition in which objects…','seem to have no weight and float','become heavier than the spacecraft','lose all physical existence','The definition describes apparent lack of weight.','meaning'),Q(1,'Which phrase is correct?','experience weightlessness','weightlessnessly float','a weightlessness of heavy','The noun names a condition one can experience.','grammar'),Q(1,'The word combines weight, -less, and…','-ness','-er','-ward','The final suffix turns the adjective into a state noun.','word-formation')]);
P('weighty','Weighty is weight + -y and can mean physically heavy or important enough to influence thought or decisions.',[C('weighty.s1','physical mass','The weighty oak door swung slowly on its hinges and needed two people to move it.','这扇沉重的橡木门在铰链上缓慢转动，需要两个人才能挪动。','weighty object; weighty book','形容物体重量大。','Two people are needed because the door is heavy.','沉重的'),C('weighty.s2','importance','The committee considered several weighty objections before approving the proposal.','委员会在批准提案前认真考虑了几项重要反对意见。','weighty issue/matter; weighty evidence','比喻指重要、足以影响决定。','The objections matter to the decision.','重大的')],M('The weighty objections were unimportant and had no effect on the committee’s decision.','The minor objections were unimportant and had no effect on the committee’s decision.','An objection that does not matter is not weighty in the figurative sense.','meaning'),[Q(1,'Why did the oak door move slowly?','It was physically heavy','It was made of paper','It had no hinges','Sense 1 means having considerable physical weight.','context'),Q(2,'Why consider the objections carefully?','They could affect the decision','They were made of oak','They were delivered by a weight','Sense 2 means important or influential.','context'),Q(1,'Which use is figurative?','a weighty issue','a weighty iron door','a weighty parcel on a scale','The issue has importance rather than physical mass.','meaning'),Q(1,'Weighty is formed from…','weight + -y','weight + -less + -ness','weigh + -er','The suffix -y forms an adjective meaning characterized by weight.','word-formation')]);
P('weird','Weird comes from Old English wyrd, “fate”; it now describes something very strange, sometimes with a mysterious or slightly frightening quality.',[C('weird.s1','unusual','A weird pattern appeared on the screen, although no one had changed the program.','屏幕上出现了一个奇怪的图案，尽管没人改过程序。','weird behavior/sound; look weird','形容非常奇怪、出乎意料。','The unexplained pattern is unusual.','奇怪的'),C('weird.s2','eerie','A weird glow came from the empty house, making the night walk feel unsettling.','空房子里透出诡异的光，让夜间散步令人不安。','weird feeling; weird and frightening','形容神秘而略带可怕或不安感。','The unexplained light makes the scene eerie.','诡异的')],M('The weird glow was completely ordinary and immediately explained by the bright lamp in the room.','The strange glow seemed to come from the empty house without an obvious cause.','A normal explained lamp would not create the mysterious effect described.','meaning'),[Q(1,'What appeared on the screen?','An unexplained unusual pattern','A scheduled weather report','A photograph of the programmer','Sense 1 is something strange or unexpected.','context'),Q(2,'Why did the glow feel weird?','It came from an empty house and felt unsettling','It was a familiar lamp in a bright room','It was sunlight at noon','Sense 2 includes a mysterious, eerie quality.','context'),Q(1,'Which sentence uses weird as an adjective?','A weird sound came from the attic.','The weirdly of the attic was loud.','She weird the sound yesterday.','Weird modifies the noun sound.','grammar'),Q(1,'The Old English source wyrd referred to…','fate','a metal seam','a field of grain','The earlier word meant fate or destiny.','word-formation')]);
P('welcome','Welcome comes from Old English wilcuma, “a desired guest”; it can mean greet warmly, accept gladly, a friendly greeting, or wanted/pleasing.',[C('welcome.s1','greeting','The host welcomed the late guests at the door and showed them to their seats.','主人在门口热情迎接迟到的客人，并领他们入座。','welcome a guest; warmly welcome someone','动词，指友好地迎接到来的人。','The host greets and receives the guests.','欢迎'),C('welcome.s2','acceptance','The team welcomed the extra time because it needed another day to finish the design.','团队乐于接受额外时间，因为他们还需要一天完成设计。','welcome a chance/change; welcome the news','动词，指欣然接受某件事。','They are pleased to receive the extra time.','乐于接受'),C('welcome.s3','greeting noun','The banner at the entrance offered a warm welcome to families arriving for the festival.','入口处的横幅向前来参加节日活动的家庭致以热烈欢迎。','give/receive a welcome; a warm welcome','名词，指友好的迎接或欢迎表示。','The banner gives visitors a friendly greeting.','欢迎'),C('welcome.s4','desired','A quiet afternoon with no meetings would be a welcome change for the busy editor.','对于忙碌的编辑来说，一个没有会议的安静下午将是令人愉快的变化。','welcome relief/change; a welcome addition','形容令人高兴、受欢迎的。','The change is wanted and pleasing.','令人愉快的')],M('The host welcomed the guests by ignoring them at the entrance and refusing to let them sit.','The host greeted the guests at the entrance and showed them to their seats.','Ignoring and refusing guests is not a friendly welcome.','meaning'),[Q(1,'What did the host do at the door?','Greeted the guests and showed them to seats','Asked them to leave immediately','Started designing a banner','Sense 1 is to greet someone warmly.','context'),Q(2,'Why did the team welcome the extra time?','It needed another day to finish the design','It had already finished weeks early','The time removed the project','Sense 2 means be pleased to accept something.','context'),Q(3,'What did the banner offer?','A friendly greeting','An extra day of work','A meeting schedule','Sense 3 is the noun meaning greeting.','context'),Q(4,'Why would the quiet afternoon be welcome?','It would be a pleasing change','It would add more meetings','It would be unwanted','Sense 4 means wanted or pleasing.','context')]);
P('welcoming','Welcoming is formed from welcome + -ing and describes a friendly, pleasant place or the act of showing gladness toward visitors.',[C('welcoming.s1','atmosphere','The café has a welcoming atmosphere, with warm lights and chairs arranged for conversation.','这家咖啡馆氛围友好，灯光温暖，座椅也便于交谈。','welcoming atmosphere/place; welcoming environment','形容场所温馨友好、令人舒适。','The setting makes people feel at ease.','宜人的'),C('welcoming.s2','receiving guests','The volunteers were welcoming the new families as they arrived at the community center.','新家庭抵达社区中心时，志愿者们正热情地迎接他们。','welcoming guests; welcoming smile','表示正在友好地接待或欢迎来客。','The volunteers show gladness at the families’ arrival.','迎接')],M('The welcoming café made newcomers feel unwelcome by turning them away at the door.','The unfriendly café made newcomers feel unwelcome by turning them away at the door.','Turning people away is not a welcoming reception.','meaning'),[Q(1,'What creates the café’s welcoming atmosphere?','Warm lights and conversation-friendly seating','A locked door and no chairs','Loud alarms and empty tables','Sense 1 describes a pleasant environment.','context'),Q(2,'What were the volunteers doing?','Greeting arriving families','Closing the center before they arrived','Installing the café lights','Sense 2 is the act of receiving guests warmly.','context'),Q(1,'A welcoming place makes visitors feel…','comfortable and accepted','physically heavier','unable to enter','Welcoming describes a friendly environment.','meaning'),Q(1,'Which phrase is natural?','a welcoming smile','a welcomeing smile','a welcomingly visitor','Welcoming is the adjective before smile.','grammar')]);
P('weld','Weld is an English verb for joining pieces by heating until they fuse; its historical origin is uncertain, so this entry makes no more specific root claim.',[C('weld.s1','metalwork','The technician welded the steel frame at each joint before checking its strength.','技术员在检查强度前把钢架的每个接缝都焊接起来。','weld two pieces together; weld metal','动词，指加热金属使其熔合连接。','Heat fuses the pieces at their joint.','焊接'),C('weld.s2','figurative unity','Shared experience welded the two teams into a close working group.','共同经历把两个团队凝聚成了紧密合作的集体。','weld a group together; welded by a common goal','比喻指把人或观念紧密结合起来。','The experience unites the teams.','使紧密结合'),C('weld.s3','joint noun','The inspector found a crack in the weld connecting the pipe to the tank.','检查员在连接管道与储罐的焊缝上发现了一道裂纹。','inspect a weld; strong weld','名词，指焊接后形成的接缝。','The crack lies in the fused joint.','焊缝')],M('The welder joined the steel pieces without heating or fusing them at all.','The welder joined the steel pieces by heating them until they fused.','Welding joins metal through heat and fusion.','meaning'),[Q(1,'How did the technician join the frame?','By welding the steel at each joint','By tying it with paper ribbon','By cooling it without joining','Sense 1 is the metalworking verb.','context'),Q(2,'What did shared experience do to the teams?','Brought them into a close group','Separated them into rivals','Made a crack in a pipe','Sense 2 is the figurative verb.','context'),Q(3,'Where was the crack?','In the fused joint between pipe and tank','In a paper greeting card','In the inspector’s ruler','Sense 3 uses weld as a noun for the joint.','context'),Q(1,'Which phrase is standard?','weld two metal pieces together','weld two metal pieces apart into','weld the pieces without heat','The common construction describes joining by fusion.','collocation')]);
P('welfare','Welfare combines well + fare, “a way of faring”; it means health and well-being, or government aid for people in need.',[C('welfare.s1','well-being','The committee put the children’s welfare first when it chose a safer school route.','委员会选择更安全的上学路线时，把孩子们的福祉放在首位。','public welfare; welfare of children','名词，指个人或群体的健康、幸福和安康。','The decision protects the children’s well-being.','福祉'),C('welfare.s2','assistance','The family received temporary welfare while the parent searched for a new job.','家长寻找新工作期间，这个家庭获得了临时社会救助。','welfare benefits; welfare recipient','名词，指政府给有需要者的经济和实际援助。','The payments help the family meet basic needs.','社会救助')],M('The family received welfare benefits even though the program gave no money or practical help.','The family received no welfare benefits because the program provided no money or practical help.','Welfare assistance refers to help, not its absence.','meaning'),[Q(1,'What did the safer route protect?','The children’s well-being','The committee’s wages','The family’s paper files','Sense 1 is health, comfort, and happiness.','context'),Q(2,'Why did the family receive temporary welfare?','A parent was searching for work','The family owned a café','The school route was shorter','Sense 2 is practical or financial government aid.','context'),Q(1,'Which phrase is idiomatic?','the welfare of children','the welfarely children','welfare to children’s well','Welfare is used in the of phrase to name whose well-being matters.','grammar'),Q(2,'A welfare benefit is…','government assistance for someone in need','a private weight used to hold paper','a formal welcome','The second sense concerns aid.','meaning')]);
P('well','Well comes from Old English wel, “in a good way”; it is also used for degree, health, a deep water hole, and liquid rising or flowing.',[C('well.s1','manner','The mechanic repaired the bicycle well, and it rode smoothly on the first test.','修车师傅把自行车修得很好，第一次试骑就很顺畅。','work/speak well; do well','副词，指做得好、熟练或令人满意。','The repair succeeds and the bike works.','好地'),C('well.s2','degree','The village is well beyond the bridge, so allow another hour for the walk.','村子远在桥的另一边，所以步行还要再留出一小时。','well beyond/over; well aware','副词，表示程度很大或远远地。','The location is a considerable distance beyond the bridge.','远远地；充分地'),C('well.s3','health','After two days of rest, Mina felt well enough to return to work.','休息两天后，米娜感觉身体恢复得可以上班了。','feel/look well; get well','形容词，指健康、身体状况良好。','She has recovered enough to work.','健康的'),C('well.s4','water source','The farm draws clean water from a stone well behind the barn.','农场从谷仓后的一口石井里取用干净的水。','dig/draw water from a well; oil well','名词，指从地下取水或油的深井。','Water is taken from a deep hole in the ground.','井'),C('well.s5','flow','Clear water began to well up through the sand after the pump stopped.','水泵停止后，清水开始从沙地里涌出。','tears/water well up; well up from','动词，指液体涌出或向上流动。','The water rises and flows to the surface.','涌出')],M('The mechanic repaired the bicycle well, but it fell apart during the first test ride.','The mechanic repaired the bicycle poorly, and it fell apart during the first test ride.','A repair that fails immediately was not done well.','meaning'),[Q(1,'How did the bicycle ride after the repair?','Smoothly','It stayed broken','It floated in a well','Sense 1 means in a satisfactory manner.','context'),Q(2,'How far is the village from the bridge?','Well beyond it','Directly under it','Only a few steps before it','Well intensifies the distance in sense 2.','context'),Q(3,'Why could Mina return to work?','She felt healthy enough','She found a deep water hole','She was far beyond the bridge','Sense 3 describes health.','context'),Q(4,'Where did the farm get water?','From a deep well behind the barn','From a paperweight','From the west wind','Sense 4 is the underground water source.','context')]);
P('well-being','Well-being combines well + being and names a healthy, happy, comfortable state for a person or a good condition of life for a community.',[C('well-being.s1','personal health','Regular sleep and time outdoors improved the patient’s physical and emotional well-being.','规律睡眠和户外活动改善了病人的身心健康。','physical/emotional well-being; support well-being','名词，指个人健康、幸福和舒适的状态。','The habits improve the person’s health and happiness.','身心健康'),C('well-being.s2','community','The council measured residents’ well-being by asking about safety, housing, and access to parks.','市议会通过询问安全、住房和公园使用情况来衡量居民的生活福祉。','community/social well-being; improve public well-being','名词，指个人或社区良好的生活状况。','The survey evaluates conditions across the community.','生活福祉')],M('The policy improved public well-being by removing safe housing and access to parks.','The policy harmed public well-being by removing safe housing and access to parks.','Removing basic supports worsens rather than improves residents’ well-being.','meaning'),[Q(1,'What improved the patient’s well-being?','Sleep and outdoor time','A lack of rest','A distant water well','Sense 1 is personal health and happiness.','context'),Q(2,'What did the council ask residents about?','Safety, housing, and parks','The weight of their luggage','Which team they welcomed','Sense 2 covers community living conditions.','context'),Q(1,'Well-being refers to…','health, happiness, and comfort','a single vote in an election','a seam joining two metal parts','The compound names a positive state of life.','meaning'),Q(1,'Which phrase is standard?','emotional well-being','well-beingly emotional','wellness being of','Well-being is a noun used after an adjective such as emotional.','grammar')]);
P('well-heeled','Well-heeled is an informal expression meaning wealthy; its original “well equipped with heels” image developed into a figurative sense of being prosperous.',C('well-heeled.s1','wealth','The well-heeled donor paid for the library renovation without asking for public funding.','这位富有的捐赠者承担了图书馆翻修费用，没有申请公共拨款。','well-heeled investor/family; the well-heeled','非正式形容词，指富有的。','The donor can afford to fund a major renovation.','富有的'),M('The well-heeled donor could not afford even the smallest library repair.','The cash-strapped donor could not afford even the smallest library repair.','Someone unable to pay for a small repair is not wealthy.','meaning'),[Q(1,'What did the well-heeled donor pay for?','The library renovation','A bridge inspection only','A ticket to the festival','Well-heeled means wealthy.','context'),Q(1,'The phrase well-heeled is…','informal and means rich','a formal term for good footwear only','a verb meaning to weld','The source entry marks it as an informal wealth expression.','register'),Q(1,'Which sentence uses well-heeled naturally?','A well-heeled family bought the estate.','The well-heeled moneyed the estate.','She well-heeledly arrives.','The adjective describes a wealthy family.','grammar'),Q(1,'A well-heeled person is most likely to…','have substantial financial resources','be unable to pay any bill','work as a metal welder','The idiom describes affluence.','meaning')]);
P('well-known','Well-known combines well + known and means widely recognized, or familiar because one has met or heard something often.',[C('well-known.s1','fame','The well-known scientist gave a public lecture that drew a large crowd.','这位知名科学家举办了公开讲座，吸引了很多听众。','well-known author/person; become well-known','形容为许多人所知的。','Many people recognize the scientist.','知名的'),C('well-known.s2','familiarity','The route is well-known to local hikers because they use it every weekend.','当地徒步者熟悉这条路线，因为他们每个周末都会走。','well-known to someone; a well-known fact','形容因反复听说或接触而熟悉的。','Local hikers have encountered the route many times.','熟悉的')],M('The scientist was well-known to nobody and had never been mentioned in public.','The scientist was unknown to the public and had never been mentioned in public.','If nobody knows someone, well-known is not the right description.','meaning'),[Q(1,'Why did the lecture draw a crowd?','The scientist was widely recognized','The scientist was unknown to everyone','The route was familiar to hikers','Sense 1 means known about by many people.','context'),Q(2,'Why was the route well-known to local hikers?','They used it every weekend','They had never seen it','It was on another continent','Sense 2 means familiar through repeated experience.','context'),Q(1,'Which phrase is natural?','a well-known scientist','a known-well scientistly','a well-known of scientist','Well-known commonly appears before a noun.','grammar'),Q(1,'What is the difference in the two examples?','One is widely recognized; the other is familiar from use','Both mean physically heavy','One describes a government payment','The source senses distinguish public recognition from familiarity.','meaning')]);
P('well-liked','Well-liked combines well + liked and describes someone pleasing to most people or something well received by its users or audience.',[C('well-liked.s1','person','The well-liked coach listened carefully to every player and treated the whole team fairly.','这位受人喜爱的教练认真倾听每位队员，并公平对待全队。','well-liked teacher/colleague; become well-liked','形容受到多数人喜爱、评价好。','The players respond positively to the coach.','受人喜爱的'),C('well-liked.s2','product','The well-liked radio program kept its audience after moving to a new time slot.','这档广受欢迎的广播节目改到新时段后仍留住了听众。','well-liked product/show; a well-liked choice','形容受到使用者或观众欢迎的。','Listeners continue to choose the program.','受欢迎的')],M('The well-liked coach was disliked by nearly every player and treated the team unfairly.','The unpopular coach was disliked by nearly every player and treated the team unfairly.','Someone disliked by nearly everyone is not well-liked.','meaning'),[Q(1,'Why was the coach well-liked?','He listened and treated players fairly','He ignored the whole team','He canceled every practice','Sense 1 is a person thought of positively.','context'),Q(2,'What showed that the program was well-liked?','Its audience stayed after the schedule change','No one listened to it','It was replaced before airing','Sense 2 describes a show well received by its audience.','context'),Q(1,'Which sentence is natural?','She is a well-liked colleague.','She is a liked-wellly colleague.','She well-liked the colleague yesterday.','Well-liked is an adjective describing the colleague.','grammar'),Q(1,'Well-liked can describe…','people and products or shows','only a deep water source','only an east-west direction','The source includes both personal and audience reception.','meaning')]);
P('well-off','Well-off is an informal compound meaning financially comfortable or, more broadly, in a good situation.',[C('well-off.s1','money','The well-off couple could afford to restore the old house without taking out a loan.','这对经济宽裕的夫妇不用贷款就能翻修旧房。','well-off family/person; comfortably well-off','形容有不少钱、经济宽裕。','They can pay for the work without borrowing.','富裕的'),C('well-off.s2','circumstances','After recovering from the illness and finding steady work, the family was much better off.','病愈并找到稳定工作后，这个家庭的处境好多了。','be well-off; better/worse off','形容整体处境不错，不仅指有钱。','Their health and employment situation have improved.','处境良好的')],M('The well-off couple could not pay for repairs and had no savings or income.','The financially struggling couple could not pay for repairs and had no savings or income.','Lacking money and savings contradicts the financial sense of well-off.','meaning'),[Q(1,'How could the couple restore the house?','They could afford it without a loan','They had no savings or income','They had to sell the house first','Sense 1 means financially comfortable.','context'),Q(2,'Why was the family better off after recovery?','Its health and work situation improved','It became a deep water well','It lost its steady job','Sense 2 concerns overall circumstances.','context'),Q(1,'Which phrase is standard?','be better off','be betterly offed','be off well to','The comparative expression is better off.','grammar'),Q(1,'Well-off can refer to…','wealth or broader circumstances','only a metal seam','a formal ballot','The source includes both financial and general good situations.','meaning')]);
P('well-paid','Well-paid combines well + paid and describes a job offering substantial pay or work that brings good earnings.',[C('well-paid.s1','job','The well-paid engineering post attracted applicants from several countries.','这份薪酬优厚的工程职位吸引了来自多个国家的申请者。','well-paid job/post; highly paid work','形容工作报酬高。','The position offers substantial pay.','高薪的'),C('well-paid.s2','work','She took on a well-paid contract that earned enough to cover the studio’s expenses.','她接下一份报酬丰厚的合同，收入足以支付工作室的开支。','well-paid contract/work; a well-paid assignment','形容一项工作或合同能带来丰厚收入。','The contract pays enough to cover the costs.','报酬丰厚的')],M('The well-paid position offered no salary or other compensation.','The unpaid position offered no salary or other compensation.','A position with no compensation is unpaid, not well-paid.','meaning'),[Q(1,'Why did the engineering post attract applicants?','It offered substantial pay','It had no salary','It was only a short welcome speech','Sense 1 describes a high-paying job.','context'),Q(2,'What did the contract earn?','Enough to cover the studio’s expenses','No money at all','A new water well','Sense 2 describes remunerative work.','context'),Q(1,'Which phrase is standard?','a well-paid position','a paid-well positionly','a well-payingly job','Well-paid is an adjective placed before position.','grammar'),Q(1,'A well-paid contract is one that…','brings good earnings','requires payment from the worker','is necessarily unpaid','The source sense describes work that earns well.','meaning')]);
P('well-to-do','Well-to-do is an idiom meaning prosperous or financially comfortable, though not necessarily extremely rich.',C('well-to-do.s1','prosperity','The well-to-do neighbors donated to the clinic but still lived more modestly than the city’s wealthiest families.','这些富裕的邻居向诊所捐款，但生活仍比城里最富有的家庭朴素。','well-to-do household/family; the well-to-do','形容富裕、生活宽裕，但未必极其有钱。','They can afford to donate while living modestly.','富裕的'),M('The well-to-do household could not afford basic food or a safe place to live.','The impoverished household could not afford basic food or a safe place to live.','Severe poverty conflicts with the meaning of prosperous.','meaning'),[Q(1,'What did the well-to-do neighbors do?','Donated to the clinic','Asked the clinic for emergency food','Moved into the city’s poorest shelter','The phrase describes people with comfortable resources.','context'),Q(1,'Does well-to-do necessarily mean extremely rich?','No, it means prosperous but not necessarily very rich','Yes, it always means among the wealthiest','No, it means unable to pay for necessities','The source definition explicitly allows comfortable but non-extreme wealth.','meaning'),Q(1,'Which phrase is natural?','a well-to-do family','a to-do-well familyly','the family well-to-doed','The idiom functions as an adjective before family.','grammar'),Q(1,'Well-to-do is closest in meaning to…','prosperous','destitute','weightless','It describes financial comfort.','meaning')]);
P('welt','Welt is probably related to Germanic words for a strip or ridge; it names a raised mark after a blow and a strip of leather in shoe construction.',C('welt.s1','mark','A red welt appeared on his arm where the ball had struck him.','球击中的地方，他手臂上出现了一道红色隆起。','a raised welt; welt from a blow','名词，指受到击打后皮肤上隆起的痕迹。','The impact leaves a ridge on the skin.','肿痕'),M('The ball left a smooth hollow in his arm, with no raised mark at all.','The ball left a welt on his arm, a raised mark from the impact.','A welt is raised rather than hollow.','meaning'),[Q(1,'Where did the welt appear?','On the arm where the ball struck','On the shoe’s sole','At the western edge of the field','Sense 1 is a raised mark after a blow.','context'),Q(1,'A welt on skin is…','a raised ridge','a deep well for water','a smooth flat area with no mark','The term describes a ridge left by impact.','meaning'),Q(1,'Which phrase is natural?','a welt from a blow','a welt of east','weltly arm','The phrase links a welt to the impact that caused it.','collocation'),Q(1,'Welt can also name…','a leather strip between parts of a shoe','a wind blowing from the west','a kind of wheat','The source entry also uses welt for shoe construction.','meaning')]);
P('west','West is from Old English west, the direction where the sun sets; it can name that direction, a western region, or movement toward/from it.',[C('west.s1','direction','The trail turns west after the river and continues toward the setting sun.','小路过河后向西转，继续通向落日的方向。','to the west; west of the river','名词，指东的相反方向、太阳落下的一方。','The path follows the sunset direction.','西方'),C('west.s2','region','Her grandparents live in the west of the country, several hours from the capital.','她的祖父母住在该国西部，离首都几小时路程。','the west of a country; the American West','名词，指国家或地区的西部，也可指西方国家。','Their home lies in the country’s western region.','西部'),C('west.s3','directional adverb','The migrating birds flew west for two days before reaching the coast.','迁徙的鸟儿向西飞了两天后到达海岸。','head/travel/fly west; westward','副词，指朝西或从西面。','The birds travel toward the west.','向西')],M('The birds flew west, moving steadily toward the sunrise in the east.','The birds flew east, moving steadily toward the sunrise.','Flying toward sunrise is eastward, not westward.','meaning'),[Q(1,'Which way does the trail turn after the river?','West','North','Straight down into the river','Sense 1 names the direction opposite east.','context'),Q(2,'Where do the grandparents live?','In the country’s western region','In the capital itself','In the easternmost village','Sense 2 refers to a region.','context'),Q(3,'Which way did the migrating birds fly?','Toward the west','Toward the sunrise in the east','In a circle over the river','Sense 3 is the directional adverb.','context'),Q(1,'The sun sets in the…','west','east','north','The basic compass direction is associated with sunset.','meaning')]);
P('westerlies','Westerlies is formed from west + -erly and names winds that come from the west, especially prevailing mid-latitude wind belts.',C('westerlies.s1','meteorology','The westerlies carried moist air across the ocean and brought rain to the island’s western coast.','西风带把潮湿空气吹过海洋，给岛屿西岸带来了降雨。','prevailing westerlies; belt of westerlies','名词复数，指来自西方的风，尤指中纬度盛行风带。','The winds blow from the west across the ocean.','西风带'),M('The westerlies blew steadily from the east toward the west across the ocean.','The easterlies blew from the east toward the west across the ocean.','Westerlies come from the west; winds from the east are easterlies.','meaning'),[Q(1,'What did the westerlies carry across the ocean?','Moist air','A group of migrating whales','A bundle of wheat','Westerlies are winds that transport air.','context'),Q(1,'Westerlies are winds that come…','from the west','from the north only','from underground','Their name and definition identify their direction of origin.','meaning'),Q(1,'Which phrase is standard?','prevailing westerlies','prevailing westliesly','a westerlies of east','The plural noun commonly appears in the phrase prevailing westerlies.','collocation'),Q(1,'Westerlies is formed from west +…','-erly','-ness','-less','The suffix -erly forms the directional adjective/noun.','word-formation')]);
P('westerner','Westerner is western + -er and means a person from a Western country or, in a narrower use, the western United States.',[C('westerner.s1','region','The visiting westerner asked the local guide about customs in the coastal village.','来访的西方人向当地向导询问沿海村庄的风俗。','a Western westerner; a westerner from Europe','名词，指来自西方国家的人。','The visitor comes from a Western country.','西方人'),C('westerner.s2','United States','The rancher, a lifelong westerner, knew the mountain roads across Wyoming well.','这位终身生活在美国西部的牧场主熟悉怀俄明州的山路。','a western U.S. westerner; lifelong westerner','名词，指居住在美国西部的人。','The rancher lives in the western part of the United States.','美国西部人')],M('The lifelong westerner had never lived in the American West or any Western country.','The lifelong eastern resident had never lived in the American West or any Western country.','Someone who has never lived in the West is not a lifelong westerner.','meaning'),[Q(1,'Where was the visiting person from?','A Western country','The coastal village itself','A mountain road in Wyoming','Sense 1 means someone from a Western country.','context'),Q(2,'Why was the rancher a westerner?','He had lived in the western United States all his life','He had never visited the West','He had just arrived from Europe','Sense 2 specifically refers to the U.S. West.','context'),Q(1,'A westerner is…','a person from the West','a wind that blows eastward','a deep hole for water','The suffix -er names a person associated with the West.','meaning'),Q(1,'Which phrase is standard?','a lifelong westerner','a westeringly person','a westerner of lifetimeed','Westerner is a person noun.','grammar')]);
P('western region','Western region combines western + region and means a country’s part lying to the west or a broad tract of land in the west.',[C('western region.s1','country geography','The western region of the country receives less rain than the eastern coast.','该国西部地区的降雨量比东海岸少。','the western region of a country; western region office','名词短语，指国家西侧的区域。','It lies west of the rest of the country.','西部地区'),C('western region.s2','large area','The explorers crossed a vast western region before reaching the central plateau.','探险者穿过辽阔的西部地域后才抵达中央高原。','a vast western region; western region of a continent','名词短语，指大陆或广阔地域的西部大片区域。','The tract is a broad area lying westward.','西方广阔地区')],M('The western region lay east of the entire country and received the eastern coast’s rainfall.','The eastern region lay east of the country and received the eastern coast’s rainfall.','A western region is on the west side, not the east.','meaning'),[Q(1,'How did rainfall in the country’s western region compare?','It received less rain than the eastern coast','It received more rain than every other place','It lay outside the country','Sense 1 identifies a country’s western part.','context'),Q(2,'What did the explorers cross?','A vast western tract before the plateau','A small eastern island','A deep water well','Sense 2 can refer to a broad western area.','context'),Q(1,'Which phrase is standard?','the western region of the country','the country western regionly','region to westernly','The phrase uses the modifier western before region.','grammar'),Q(1,'A western region is located…','to the west of a larger area','only at the center of the earth','north of every western country','The compound is a geographic area in the west.','meaning')]);
P('western','Western comes from west + -ern and describes the western part of a region, the American West, or ideas and customs of Western countries.',[C('western.s1','geography','The western counties receive cooler ocean air than the dry interior.','西部各郡受到的海洋冷空气比干燥内陆更多。','western coast/region; western side','形容属于国家或地区西部的。','The counties lie on the west side.','西部的'),C('western.s2','United States','The western ranch is known for its wide grassland and long cattle drives.','这座美国西部牧场以辽阔草原和长途赶牛闻名。','the western United States; a western ranch','形容来自美国西部或与其相关的。','The ranch is in the American West.','美国西部的'),C('western.s3','culture','The course compares Western ideas about individual rights with other political traditions.','这门课程比较西方关于个人权利的观念与其他政治传统。','Western culture/values; Western countries','形容与西方国家的思想、习俗或价值观有关。','The comparison concerns cultural and political traditions.','西方的')],M('The western counties lie on the country’s eastern coast beside the sunrise.','The eastern counties lie on the country’s eastern coast beside the sunrise.','The modifier for the sunrise side is eastern, not western.','meaning'),[Q(1,'What kind of air reaches the western counties?','Cooler ocean air','Dry air from the eastern coast only','Air from an underground well','Sense 1 describes geographic position.','context'),Q(2,'What is the western ranch known for?','Grassland and cattle drives in the American West','A European capital’s subway','A coastal whale sanctuary','Sense 2 is specific to the western United States.','context'),Q(3,'What traditions does the course compare?','Western ideas about individual rights and other traditions','Only western county weather','Different kinds of wheat','Sense 3 concerns Western values and customs.','context'),Q(1,'Which phrase is correct?','Western political traditions','the Westly political ideas','political Westernsly traditions','Western is the adjective form used before traditions.','grammar')]);
P('westward','Westward combines west + -ward and means toward the west or pointing/facing that direction.',[C('westward.s1','movement','The hikers continued westward until the sun disappeared behind the ridge.','徒步者继续向西走，直到太阳消失在山脊后。','travel/head westward; move westward','副词，指朝西移动。','Their route goes toward the west.','向西'),C('westward.s2','orientation','The westward-facing windows caught the last light of the evening.','朝西的窗户接住了傍晚最后一缕光。','westward-facing; westward view','形容词，指朝向西方的。','The windows point toward the west.','朝西的')],M('The hikers walked westward toward the sunrise in the east.','The hikers walked eastward toward the sunrise in the east.','Movement toward sunrise is eastward, not westward.','meaning'),[Q(1,'Where did the hikers continue?','Toward the west','Toward the sunrise in the east','Straight down the ridge','Sense 1 is movement west.','context'),Q(2,'Which windows caught the last evening light?','Those facing west','Those facing north underground','Those pointing east at sunrise','Sense 2 describes orientation.','context'),Q(1,'Which phrase is natural?','a westward journey','a westwardly travel to','a journey to westwardness','Westward describes direction or orientation.','grammar'),Q(1,'The suffix -ward in westward means…','in the direction of','without','the state of being','The compound indicates movement or facing toward the west.','word-formation')]);
P('wet','Wet is related to Old English wǣt and describes something covered in liquid, rainy weather, making something damp, or rain/water itself.',[C('wet.s1','surface','The wet pavement reflected the streetlights after the evening rain.','傍晚下雨后，湿漉漉的人行道映出路灯的光。','wet clothes/ground; get wet','形容被水或其他液体覆盖、尚未干燥。','The pavement still carries rainwater.','湿的'),C('wet.s2','weather','It was a wet spring, with rain falling on nearly every weekend.','那年春天多雨，几乎每个周末都在下雨。','wet weather; a wet season','形容雨水很多的天气。','Frequent rain defines the season.','多雨的'),C('wet.s3','make damp','Wet the cloth with warm water before wiping the table.','擦桌子前先用温水把布弄湿。','wet a cloth; wet your hair','动词，指使某物变湿。','Water is added to the cloth.','弄湿'),C('wet.s4','rain noun','After weeks without rain, the farmers hoped for a little wet before planting.','数周没有下雨后，农民希望播种前能下点雨水。','the wet; a spell of wet','名词，指雨或使地面变湿的水。','They hope for precipitation to moisten the soil.','雨水')],M('She wet the cloth by keeping it completely dry before wiping the table.','She dampened the cloth with warm water before wiping the table.','A dry cloth has not been wetted.','meaning'),[Q(1,'What reflected the streetlights?','The wet pavement','A dry mountain ridge','A glass of milk indoors','Sense 1 means covered with liquid.','context'),Q(2,'Why was spring called wet?','Rain fell on nearly every weekend','It had no rain for weeks','It was unusually hot and dry','Sense 2 describes rainy weather.','context'),Q(3,'What should happen to the cloth before wiping?','It should be made damp with warm water','It should be kept dry','It should be frozen','Sense 3 uses wet as a verb.','context'),Q(4,'What did farmers hope for?','A little rain to moisten the soil','More dry weeks','A new wheelchair','Sense 4 is the noun meaning rain or water.','context')]);
P('wetland','Wetland combines wet + land and means land covered by water for much of the year, including low ground where water collects.',[C('wetland.s1','ecosystem','Herons nested in the wetland, where shallow water covered the reeds through most of the year.','苍鹭在湿地筑巢，那里的浅水大部分时间都淹没着芦苇。','protect/preserve a wetland; wetland habitat','名词，指一年中大部分时间有水或非常潮湿的土地。','The land stays waterlogged for much of the year.','湿地'),C('wetland.s2','low-lying geography','The wetland formed in a low basin where the river spread out before meeting the sea.','湿地形成在河流入海前扩散的一处低洼盆地。','coastal wetland; low-lying wetland','名词，指常积水的低地，常见于河口附近。','Water gathers in the low ground near the coast.','低洼湿地')],M('The wetland remained dry all year, with no standing water or damp soil.','The upland remained dry all year, with no standing water or damp soil.','Land that stays dry is not a wetland.','meaning'),[Q(1,'Where did the herons nest?','In the shallow, water-covered wetland','On a dry mountain peak','Inside the café’s window','Sense 1 is persistently wet land and habitat.','context'),Q(2,'Where did the basin wetland form?','Where the river spread before reaching the sea','On a dry ridge far from water','Inside a wheat silo','Sense 2 is a low place where water collects.','context'),Q(1,'A wetland is land that…','is wet for much of the year','is always desert-dry','has no soil','The compound names waterlogged land.','meaning'),Q(1,'Which phrase is natural?','wetland habitat','wetly land habitat','habitat of wetlandly','Wetland modifies habitat as a noun modifier.','grammar')]);
P('wetware','Wetware is a computer-science metaphor formed on hardware/software; it refers jokingly to the human brain and nervous system.',C('wetware.s1','computing metaphor','The programmer blamed the mistake on wetware: she had forgotten to save the file before closing it.','程序员把错误归咎于“湿件”：她关文件前忘了保存。','human wetware; wetware error','名词，幽默地指作为生物系统的人脑和神经系统。','The error came from a human rather than the computer.','人脑系统'),M('The laptop’s wetware was a silicon chip that stored the program after the user left.','The laptop’s hardware was a silicon chip that stored the program after the user left.','Wetware refers to biological human cognition, not a machine chip.','meaning'),[Q(1,'Why did the programmer mention wetware?','A human forgot to save the file','A silicon chip failed','The computer ran out of electricity','Wetware humorously points to the human operator.','context'),Q(1,'Wetware is a metaphor for…','the brain and nervous system','the metal case of a computer','the programs installed on a device','The term is the biological counterpart in the hardware/software metaphor.','meaning'),Q(1,'Which phrase is natural?','a wetware error','an error in the wetwarely','a wetware of silicon','The term can humorously describe a human-caused mistake.','collocation'),Q(1,'Wetware was coined by analogy with…','hardware and software','welfare and westward','water and wheat','The word extends the computer terminology analogy to the human system.','word-formation')]);
P('whale','Whale comes from Old English hwæl and names a very large sea mammal; figuratively it can describe something unusually large or excellent in “a whale of a…”.',[C('whale.s1','animal','A whale surfaced beside the research boat to breathe before diving beneath the waves.','一头鲸在科考船旁浮出水面呼吸，随后潜入海浪之下。','blue whale; whale surfaces/breaches','名词，指体型很大的海洋哺乳动物。','It breathes air and returns underwater.','鲸'),C('whale.s2','figurative size','The museum acquired a whale of a fossil, nearly ten meters long and too large for its old display case.','博物馆得到了一块极大的化石，近十米长，旧展柜根本装不下。','a whale of a time/thing; a whale of a fossil','口语比喻，指特别大的东西；a whale of a…也可表示非常好的经历。','The fossil is unusually large.','巨大的东西')],M('The whale surfaced to breathe because it could extract oxygen from the water like a fish.','The whale surfaced to breathe air before diving again.','Whales are mammals that breathe air, unlike fish.','meaning'),[Q(1,'Why did the whale surface?','To breathe air','To lay eggs on the boat','To use the boat as a lung','Sense 1 is an air-breathing sea mammal.','context'),Q(2,'Why was the fossil called a whale of a fossil?','It was unusually large','It was a living whale','It was too small to see','Sense 2 uses whale figuratively for great size.','context'),Q(1,'Which sentence uses whale figuratively?','We had a whale of a time at the festival.','A whale breathed at the surface.','The whale swam under the boat.','The idiom means a very good or enjoyable time.','meaning'),Q(1,'A whale is a…','large sea mammal','small grain crop','tool for holding metal','The animal is a mammal, not a fish.','meaning')]);
P('wharf','Wharf is an old English word for a flat waterfront structure where ships load and unload or tie up.',[C('wharf.s1','cargo','Crates of tea were stacked on the wharf while workers prepared to load the ship.','工人准备装船时，码头上堆放着一箱箱茶叶。','load/unload at a wharf; wharf facilities','名词，指船舶装卸货物的滨水平台。','Cargo is moved between the ship and shore there.','码头'),C('wharf.s2','mooring','The fishing boat remained tied to the wharf overnight while its engine was repaired.','渔船夜间系泊在码头边，同时修理发动机。','tie up at a wharf; wharf berth','名词，指港口中供船只停靠系缆的地方。','The boat is secured alongside the port structure.','停船码头')],M('The crew loaded the crates while the ship was tied to a wharf several miles inland from any water.','The crew loaded the crates while the ship was tied to a wharf beside the harbor.','A wharf is a structure built next to water for ships.','meaning'),[Q(1,'Where were the tea crates stacked?','On the waterfront wharf','Inside the well beneath the barn','In a dry field west of town','Sense 1 is the cargo-handling structure.','context'),Q(2,'Where did the fishing boat stay overnight?','Tied to the wharf','Floating in a wheat field','Parked on a road','Sense 2 concerns mooring in port.','context'),Q(1,'Which phrase is correct?','unload cargo at a wharf','unload cargo on a wharfless','wharf the cargo to inland','Ships load and unload cargo at a wharf.','collocation'),Q(1,'A wharf is built…','beside water','at the center of a dry desert','inside a computer','The waterfront location is central to its meaning.','meaning')]);
P('what','What descends from Old English hwæt and asks for information, identifies a thing, stands for “the thing(s) that,” or expresses degree in exclamations.',[C('what.s1','question','What did the mechanic repair on the bicycle?','修车师傅修了自行车的什么部位？','what happened; what did you see?','疑问词，用来询问事物或动作的信息。','The speaker asks which thing was repaired.','什么'),C('what.s2','determiner/exclamation','What a remarkable whale surfaced beside the research boat!','一头多么壮观的鲸在科考船旁浮出水面啊！','what a surprise; what book?','用于名词前询问是哪一个，或感叹某事非凡。','The phrase expresses how remarkable the whale is.','多么；哪一个'),C('what.s3','fused relative','She remembered what the guide had said about the wetland.','她记得向导关于湿地所说的话。','remember what someone said; what matters','代指“……的事情”或“……的内容”。','What the guide said is the thing remembered.','……的内容'),C('what.s4','degree','What a long way the westerlies carried the ship!','西风把船吹了多远啊！','what a lot; what a long way','用于感叹句，表示程度或数量之大。','The speaker emphasizes the great distance.','多么；多少')],M('She remembered what the guide said, but could not recall anything the guide had said.','She remembered what the guide said and could recall the information.','The sentence contradicts itself: remembering what was said means recalling it.','meaning'),[Q(1,'What did the mechanic repair?','The bicycle','The research boat’s sails','A wheat field','Sense 1 asks for information about a thing.','context'),Q(2,'What does “What a remarkable whale!” express?','Admiration for how remarkable it is','A request for the whale’s name','A question about the time','Sense 2 is exclamatory before a noun.','context'),Q(3,'What did she remember?','The guide’s words about the wetland','The exact weight of a paperweight','The place where the ship was moored','Sense 3 stands for the thing that was said.','context'),Q(4,'What does “What a long way!” emphasize?','The great distance','The direction east only','The identity of the ship','Sense 4 expresses degree in an exclamation.','context')]);
P('whatever','Whatever is what + ever and means anything at all, any kind without preference, or an informal expression of indifference or no objection.',[C('whatever.s1','anything','Take whatever you need from the supply shelf before the wet-weather trip.','去湿地考察前，从物资架上拿任何你需要的东西。','whatever happens; take whatever you need','代词，指任何发生或需要的事物。','There is no restriction on which item to take.','任何事物'),C('whatever.s2','no preference','Choose whatever route you prefer; both trails lead to the wharf.','你喜欢哪条路线就选哪条；两条小路都通往码头。','whatever route/size; whatever you like','限定词，表示哪一种都可以、不在意具体选择。','The speaker has no preference among the routes.','无论哪种'),C('whatever.s3','indifference','“We can watch the western film or the whale documentary.” “Whatever,” he replied.','“我们可以看西部片或鲸鱼纪录片。”“随便。”他回答。','whatever!; say “whatever”','单独使用时可表示不在乎或没有异议，语气有时显得冷淡。','The reply signals indifference or no objection.','随便；无所谓')],M('Choose whatever route you prefer, but only the western trail is permitted.','Choose the western route; the other trail is closed.','Offering whatever route conflicts with restricting the choice to one route.','meaning'),[Q(1,'What may the hikers take from the shelf?','Anything they need','Only a single named item','Nothing at all','Sense 1 means anything at all that is needed.','context'),Q(2,'Which route may the traveler choose?','Either route, according to preference','Only the western route','A route that does not reach the wharf','Sense 2 leaves the choice open.','context'),Q(3,'What did “Whatever” communicate in the dialogue?','Indifference or no objection','A request for a map','A promise to repair a wheel','Sense 3 uses the word alone to signal attitude.','context'),Q(1,'Which phrase is natural?','whatever you need','whatsoeverly you need','what-ever of need','Whatever introduces an unrestricted choice.','grammar')]);
P('whatsoever','Whatsoever combines what + so + ever and means “at all” or “of any kind,” strengthening a negative or indefinite statement.',C('whatsoever.s1','emphasis','The inspection found no damage whatsoever to the wharf after the storm.','检查发现风暴过后码头完全没有任何损坏。','no evidence whatsoever; no reason whatsoever','副词，常用于否定或不定表达后，加强“完全没有、丝毫没有”。','The word intensifies the denial of damage.','丝毫；任何'),M('The inspection found no damage whatsoever, but the wharf was completely destroyed.','The inspection found extensive damage, and the wharf was completely destroyed.','“No damage whatsoever” contradicts complete destruction.','meaning'),[Q(1,'What did the inspection find?','No damage at all','Some damage to every part','A new wheelchair','Whatsoever strengthens the negative no damage.','context'),Q(1,'In “no reason whatsoever,” whatsoever means…','at all or of any kind','for this reason only','very quickly','The adverb intensifies a negative phrase.','meaning'),Q(1,'Where does whatsoever usually appear?','After a negative or indefinite expression','Before every proper name','Between a verb and its subject','It commonly follows no, none, or similar words.','grammar'),Q(1,'Which sentence uses whatsoever naturally?','We received no warning whatsoever.','We whatsoever received a warning no.','She whatsoeverly warned the west.','The word reinforces the negative no warning.','grammar')]);
P('wheat','Wheat comes from Old English hwǣte; it names both the farm-grown grass and its grain, which is ground into flour.',[C('wheat.s1','crop','The farmer rotated wheat with beans to keep the soil productive.','农民轮种小麦和豆类，以保持土壤肥沃。','grow/harvest wheat; wheat crop','名词，指种植以收获谷粒的麦类作物。','The plant is cultivated in fields.','小麦'),C('wheat.s2','grain','The mill ground the wheat into flour for the bakery’s bread.','磨坊把小麦籽粒磨成面粉，供面包店制作面包。','wheat grain/flour; whole wheat','名词，指这种作物的籽粒，可用来制粉。','The grain is milled into flour.','麦粒')],M('The mill ground the wheat plant’s roots into flour instead of using its grain.','The mill ground the wheat grain into flour for baking.','Flour is made from the grain, not the roots of the plant.','meaning'),[Q(1,'Why did the farmer rotate wheat with beans?','To keep the soil productive','To turn a wharf into a field','To make the crop grow underwater','Sense 1 is the cultivated plant.','context'),Q(2,'What did the mill grind?','The wheat grain','The plant’s roots only','The farmer’s tools','Sense 2 is the grain used to make flour.','context'),Q(1,'Which phrase is natural?','harvest wheat','harvest a wheat of','wheatly harvest','Wheat is the name of the crop being harvested.','grammar'),Q(1,'Bread flour is commonly made from…','wheat grain','wheat roots','wheat leaves only','The grain is milled into flour.','meaning')]);
P('wheedle','Wheedle is an English verb attested in the seventeenth century; its exact origin is uncertain, and it means coax someone through sweet talk.',C('wheedle.s1','persuasion','The child wheedled his aunt into lending him the bicycle by promising to return it before dinner.','孩子甜言软语地劝姑妈把自行车借给他，并答应晚饭前归还。','wheedle someone into doing something; wheedle a favor','动词，指用好听话哄劝某人给东西或做事。','He persuades her with appealing talk.','哄劝'),M('She wheedled the neighbor into lending the wheel by threatening to report him.','She persuaded the neighbor to lend the wheel by asking politely and promising to return it.','Threats are coercion, not the sweet talk meant by wheedle.','meaning'),[Q(1,'What did the child persuade his aunt to do?','Lend him the bicycle','Buy a wheat field','Move westward','He wheedled her into lending it.','context'),Q(1,'How does someone wheedle another person?','With coaxing, sweet talk','By welding two pieces of steel','By issuing a legal voucher','The verb means persuade by appealing talk.','meaning'),Q(1,'Which construction is correct?','wheedle someone into lending it','wheedle someone for to lend it','wheedle someone lending into','Wheedle someone into doing something is the standard pattern.','grammar'),Q(1,'What is known about wheedle’s exact origin?','It is uncertain','It certainly comes from the Latin word for west','It was formed from wheel + -ed','The historical origin is not securely established.','word-formation')]);
P('wheel','Wheel comes from Old English hwēol; it names a rotating vehicle part or steering control, and can mean turn suddenly or push something on wheels.',[C('wheel.s1','vehicle part','The cart’s front wheel rolled over a stone and stopped beside the wharf.','手推车的前轮碾过一块石头，停在码头旁。','front/rear wheel; wheel turns','名词，指绕中心转动、帮助车辆移动的圆形部件。','The round part rotates as the cart moves.','车轮'),C('wheel.s2','steering','The captain turned the wheel to guide the ship away from the rocks.','船长转动舵轮，引导船只避开礁石。','turn/take the wheel; steering wheel','名词，指驾驶汽车或船只时转动的控制装置。','Turning the control changes the vessel’s direction.','方向盘；舵轮'),C('wheel.s3','turn suddenly','The cyclist wheeled around when she heard her name called from behind.','骑车人听见身后有人叫她的名字，便迅速转过身来。','wheel around/round; wheel to face someone','动词，指迅速转圈或突然转身。','Her body turns suddenly toward the caller.','迅速转身'),C('wheel.s4','push on wheels','Two porters wheeled the heavy cases from the station to the hotel entrance.','两名搬运工把沉重的箱子从车站推到酒店门口。','wheel a cart/case into; wheel someone along','动词，指推着有轮子的物体移动。','They push the cases on their wheels.','推着移动')],M('The captain turned the ship’s wheel, but the wheel was a round part that could not steer the ship.','The captain turned the ship’s wheel to steer away from the rocks.','In this context the wheel is the steering control.','meaning'),[Q(1,'What happened to the cart’s front wheel?','It rolled over a stone','It turned the ship away from rocks','It became a wheelchair','Sense 1 is the rotating vehicle part.','context'),Q(2,'Why did the captain turn the wheel?','To steer the ship away from rocks','To push a suitcase to a hotel','To stop a wheat crop growing','Sense 2 is a steering control.','context'),Q(3,'What did the cyclist do when she heard her name?','Turned around quickly','Wheeled a case to a station','Turned a steering wheel','Sense 3 is a sudden turn.','context'),Q(4,'How did the porters move the cases?','They pushed them on their wheels','They carried them by sea','They rolled the wheel into a field','Sense 4 is to push a wheeled object.','context')]);
P('wheelchair','Wheelchair combines wheel + chair and names a wheeled seat, manual or powered, for a person who has difficulty walking.',C('wheelchair.s1','mobility','The ramp lets wheelchair users enter the library without climbing the front steps.','斜坡让轮椅使用者无需爬正门台阶就能进入图书馆。','manual/powered wheelchair; wheelchair user','名词，指供行动不便者使用的手推或电动轮椅。','The wheeled seat provides mobility and access.','轮椅'),M('The wheelchair helped the visitor walk up the steps without sitting or using its wheels.','The wheelchair helped the visitor reach the library by rolling up the ramp.','A wheelchair is a wheeled seat used for mobility, not a device that makes someone walk.','meaning'),[Q(1,'How does the ramp help wheelchair users?','It lets them enter without climbing steps','It turns the chair into a steering wheel','It measures the library’s weight','The context concerns access for wheelchair users.','context'),Q(1,'A wheelchair is…','a seat with wheels for someone who has difficulty walking','a chair fixed to a wharf','a device for wetting cloth','The compound names a wheeled mobility seat.','meaning'),Q(1,'Which phrase is respectful and natural?','wheelchair user','wheelchairly user','user of a wheel-chairing','Wheelchair user is the standard person-first phrase.','usage'),Q(1,'Wheelchair is a compound of…','wheel + chair','wheat + chair','west + wheel','The two parts identify the seat and its wheels.','word-formation')]);
P('when','When comes from Old English hwænne and can ask about time or situation, mark a time, refer back to a time, or mean “although/considering that.”',[C('when.s1','question','When does the westerly wind usually reach the island?','西风通常什么时候到达这座岛？','when did it happen?; ask when','疑问副词，询问时间或某种情形。','The speaker asks at what time the wind arrives.','何时'),C('when.s2','time conjunction','The farmers cover the wheat seedlings when frost is forecast.','预报有霜冻时，农民会给麦苗盖上遮护物。','when it rains; when the time comes','连词，表示在某个时间或期间。','The covering takes place at the time frost is expected.','当……时'),C('when.s3','reference to prior time','The ship reached the wharf at noon, when the tide was high.','船在中午抵达码头，那时正值涨潮。','at noon, when…; the year when…','关系副词，指前面提到的时间。','When refers back to noon.','那时'),C('when.s4','concession','Why complain about the wet weather when the garden needs rain?','花园需要雨水，既然如此，何必抱怨潮湿天气呢？','why do something when…; when you consider','连词，表示“既然、考虑到”或让步。','The need for rain is a reason not to complain.','既然；考虑到')],M('Why complain about the rain when the garden needs it? Because the garden does not need any water.','The garden needs rain, so there is little reason to complain about it.','The stated reason contradicts the conclusion.','meaning'),[Q(1,'What does the speaker ask about the wind?','At what time it reaches the island','Which person owns the island','How heavy the wind is','Sense 1 asks about time.','context'),Q(2,'When do farmers cover the seedlings?','When frost is forecast','Only after the wheat is milled','Whenever the wind blows west','Sense 2 introduces a time condition.','context'),Q(3,'What time does when refer to in the ship sentence?','Noon','The next winter','The wheat harvest','Sense 3 points back to the time already mentioned.','context'),Q(4,'Why does the question say not to complain?','Because the garden needs rain','Because the garden is underwater','Because the wharf is westward','Sense 4 means considering that.','context')]);
P('whence','Whence is from Old English hwanon, “from where”; this formal adverb asks about a place, source, or cause.',C('whence.s1','origin','The guide asked whence the carved stone had come before the museum acquired it.','博物馆收藏那块雕刻石之前，向导先询问了它的来源。','from whence; whence came…','正式用语，询问来自什么地方、来源或原因。','The question asks for the stone’s origin.','从何处；源自何因'),M('The guide asked whence the stone came, then answered that nobody had asked about its source.','The guide asked where the stone came from, then investigated its source.','Asking whence means asking about a source; the sentence contradicts itself.','meaning'),[Q(1,'What did the guide want to know?','Where the carved stone came from','How much the stone weighed','When the museum opened','Whence asks about origin or source.','context'),Q(1,'Whence is best described as…','a formal word meaning from what place or cause','an informal word for a wheelchair','a term for western winds','The source defines it as a formal origin question.','meaning'),Q(1,'Which phrase is grammatical?','whence the custom arose','whence from the custom arose from','the whence customly','Whence already carries the sense “from where.”','grammar'),Q(1,'In “the village whence she came,” whence refers to…','the source place','the time she arrived','the weight she carried','The clause identifies where she came from.','context')]);
P('whenever','Whenever combines when + ever and means at any possible time or every time a repeated event occurs.',[C('whenever.s1','any time','You may use the library’s wheelchair ramp whenever the front steps are crowded.','正门台阶拥挤时，你可以随时使用图书馆的轮椅坡道。','whenever you like; call whenever needed','连词，表示任何时候都可以。','The ramp is available at any time of need.','无论何时'),C('whenever.s2','repeated event','Whenever the tide rises, water wells up through cracks in the old wharf.','每当潮水上涨，水就会从旧码头的裂缝里涌出。','whenever it rains; whenever someone visits','连词，表示每当某个重复事件发生时。','The water rises each time the tide rises.','每当')],M('Whenever the tide rose, water never appeared and the cracks stayed completely dry.','Whenever the tide rose, water flowed up through the wharf’s cracks.','The sentence says the water appears each time, so claiming it never appears is contradictory.','meaning'),[Q(1,'When may visitors use the ramp?','At any time the steps are crowded','Only once each year','Only after the library closes','Sense 1 allows use whenever it is needed.','context'),Q(2,'What happens whenever the tide rises?','Water wells up through the wharf’s cracks','The cracks disappear forever','The wheat is harvested','Sense 2 describes the repeated result.','context'),Q(1,'“You can call whenever you need help” means…','at any time you need help','only at noon','only after the event ends','Whenever means at any possible time.','meaning'),Q(1,'Which sentence describes a repeated event?','Whenever it rains, the path becomes muddy.','Whenever is the name of a wheat crop.','The wharf whenever westward.','Whenever can mean every time an event occurs.','grammar')]);
P('where','Where descends from Old English hwǣr and asks or refers to a place, a place already mentioned, or a situation or matter.',[C('where.s1','place question','Where did the whale surface beside the research boat?','鲸鱼是在什么地方靠近科考船浮出水面的？','where are you?; where did it go?','疑问副词，询问地点或去向。','The speaker asks at what place it surfaced.','哪里'),C('where.s2','place clause','The crew stacked the crates where the wharf was highest above the water.','船员把箱子堆在码头高出水面的地方。','where the road ends; stay where you are','连词，引导表示地点的从句。','The clause identifies the spot for the crates.','在……地方'),C('where.s3','reference to place','The village, where the westerlies first reach land, has a small weather station.','西风最先抵达陆地的那个村庄有一座小气象站。','the town where…; a place where…','关系副词，指代前面已提到的地点。','Where refers back to the village.','在该地点'),C('where.s4','situation','The report explains where the wetland plan stands after the council vote.','报告说明市议会表决后湿地计划目前处于什么状况。','where matters stand; where someone is in a process','比喻指事情所处的阶段或状况。','The report describes the plan’s current position.','处境；状况')],M('The report explains where the plan stands, but it gives no information about the plan’s current situation.','The report explains the plan’s current situation after the vote.','Explaining where matters stand is explaining their situation.','meaning'),[Q(1,'What does the speaker ask about the whale?','The place where it surfaced','The whale’s age','How much the boat weighs','Sense 1 asks about a location.','context'),Q(2,'Where did the crew stack the crates?','At the highest part of the wharf','Inside the whale','At a wheat farm','Sense 2 introduces the place of an action.','context'),Q(3,'What does where refer back to in the village sentence?','The village','The report','The council vote','Sense 3 points back to a previously named place.','context'),Q(4,'What does the report explain?','The wetland plan’s current status','The address of every council member','The westward direction of the wind','Sense 4 describes a situation or stage.','context')]);
P('whereabouts','Whereabouts combines where + about + -s and means a person or thing’s location, sometimes only approximately known.',[C('whereabouts.s1','location','The rescue team learned the missing hiker’s whereabouts from a radio message near the wharf.','救援队从码头附近的一条无线电消息中得知了失踪徒步者的下落。','know someone’s whereabouts; reveal the whereabouts','名词，指某人或某物所在的位置。','The message identifies where the hiker is.','下落'),C('whereabouts.s2','approximation','The pilot said the whale’s whereabouts were somewhere west of the island, not at a precise point.','飞行员说鲸鱼大约在岛屿以西，并非某个精确地点。','approximate whereabouts; whereabouts unknown','名词，指大致所在位置。','The pilot gives only an approximate location.','大致位置')],M('The pilot gave the whale’s exact whereabouts but said it could be anywhere with no estimate.','The pilot gave only an approximate whereabouts for the whale, somewhere west of the island.','An exact location and an unbounded guess are not the same.','meaning'),[Q(1,'How did the rescue team learn the hiker’s whereabouts?','From a radio message','From the wheat harvest','From the ship’s wheel','Sense 1 is someone’s location.','context'),Q(2,'How precise was the whale’s reported whereabouts?','Only approximately west of the island','An exact set of coordinates','Completely unknown and unestimated','Sense 2 means approximate location.','context'),Q(1,'Which phrase is natural?','their whereabouts are unknown','their whereabouts is unknowned','the whereaboutsly place','Whereabouts is commonly treated as a plural-form noun.','grammar'),Q(1,'Whereabouts can refer to…','a location or an approximate location','only a precise compass bearing','a person’s salary','The word covers both exact and approximate location.','meaning')]);
P('whereas','Whereas developed from where + as; it introduces a contrast or, formally, a fact that is being stated as a premise.',[C('whereas.s1','contrast','The western coast is wet in spring, whereas the inland valley is usually dry.','西海岸春季多雨，而内陆山谷通常干燥。','whereas one thing…; whereas another…','连词，用来引出与前文不同或相对照的事实。','The two locations have contrasting weather.','而；然而'),C('whereas.s2','formal premise','Whereas the wharf has served the village for a century, the council will preserve it as a historic site.','鉴于码头已为村庄服务一个世纪，市议会将把它作为历史遗址予以保护。','whereas clause; formal whereas statement','正式文件中用于提出已知事实或考虑依据。','The long history is the stated basis for preservation.','鉴于')],M('The western coast is wet, whereas the inland valley has the same rainfall pattern and is equally wet.','The western coast is wet, whereas the inland valley is usually dry.','The sentence claims a contrast and then denies that any contrast exists.','meaning'),[Q(1,'What contrast does whereas introduce?','The wet coast versus the dry inland valley','Two equally rainy regions','A person’s exact location','Sense 1 links contrasting facts.','context'),Q(2,'Why will the council preserve the wharf?','It has served the village for a century','It was built yesterday','It is located west of a wheat field','Sense 2 introduces the formal premise.','context'),Q(1,'Which punctuation is natural?','The coast is wet, whereas the valley is dry.','Whereas, the coast wet valley dry.','The coast whereas is wet dry.','Whereas connects two contrasting clauses.','grammar'),Q(1,'At the start of a formal statement, whereas can mean…','given the fact that','at what time','from which place','The formal use states a premise or consideration.','meaning')]);
P('whereby','Whereby combines where + by and means “by which,” “by means of which,” or a rule/process that produces a stated result.',[C('whereby.s1','means','The council approved a plan whereby residents can report damaged wetland paths online.','市议会批准了一项计划，居民可通过该计划在线报告湿地步道损坏情况。','a system whereby; a method whereby','关系副词，表示“通过该方法或机制”。','The plan provides the means for reporting.','凭借该方法'),C('whereby.s2','result','The agreement set a schedule whereby the wharf would close after each storm warning.','协议制定了一项日程安排，据此每次风暴预警后码头都会关闭。','an arrangement whereby; a rule whereby','关系副词，引出依据某安排而发生的结果。','The closure follows from the schedule.','据此；依照该安排')],M('The online system whereby residents report damage gave them no way to submit any reports.','The online system whereby residents report damage let them submit reports through the website.','A system whereby people report something must provide a reporting method.','meaning'),[Q(1,'How can residents report damage under the plan?','Online through the approved system','By turning the ship’s wheel','Only by mailing wheat','Sense 1 means by means of which.','context'),Q(2,'What happens after each storm warning?','The wharf closes under the agreed schedule','The wetland becomes a wheelchair','The council abolishes all reports','Sense 2 introduces a result determined by an arrangement.','context'),Q(1,'Which phrase is standard?','a procedure whereby users apply','a procedure whereabout users apply','a whereby procedurely','Whereby introduces the method or rule.','grammar'),Q(1,'Whereby is closest in meaning to…','by which','during which','in spite of which','The word expresses the means by which something happens.','meaning')]);
P('wherever','Wherever combines where + ever and means in every place that applies or any place at all when the exact location does not matter.',[C('wherever.s1','all applicable places','Wherever the trail crosses a wetland, wooden boards keep hikers above the water.','步道每逢穿过湿地，都会铺设木板让徒步者走在水面之上。','wherever you go; wherever the road leads','连词，指凡是提到的每个地方。','The rule applies at every wetland crossing.','无论哪里'),C('wherever.s2','any place','We can stop wherever you like along the western road because the schedule is flexible.','西行路上你想在哪里停都可以，因为时间安排很灵活。','sit wherever; go wherever you choose','副词，指任何地点，具体是哪一处并不重要。','The traveler may choose any stopping place.','任何地方')],M('Wherever the trail crosses a wetland, hikers are forced to walk through unmarked deep water.','Wherever the trail crosses a wetland, boards let hikers stay above the water.','The context says a boardwalk is provided at every crossing, not that hikers must wade.','meaning'),[Q(1,'What happens at every wetland crossing?','Boards keep hikers above the water','The trail disappears completely','A wharf is built in every field','Sense 1 means at every place where the condition applies.','context'),Q(2,'Where may the group stop on the western road?','At any place they choose','Only at one named wharf','Nowhere along the route','Sense 2 leaves the location open.','context'),Q(1,'“Wherever you go, call me” means…','call me in any place you go','call only at the western coast','ask which place you prefer','Wherever applies regardless of the particular place.','meaning'),Q(1,'Which phrase is correct?','sit wherever you like','sit whereever you likes','whereverly sit you','Wherever introduces an unrestricted place choice.','grammar')]);
P('whether','Whether is from Old English hwæther, “which of two”; it introduces alternatives in indirect questions or says the choice does not matter.',[C('whether.s1','alternatives','The guide asked whether the hikers wanted the western trail or the path beside the wetland.','向导问徒步者想走西边的小路，还是走湿地旁的小路。','whether to go; ask whether…or…','连词，引出两个可能选项，常用于间接疑问句。','The hikers must choose between two routes.','是否；还是'),C('whether.s2','regardless','Whether the wind is wet or dry, the ferry leaves at six every morning.','无论风是潮湿还是干燥，渡船每天早上六点出发。','whether or not; whether…or…','连词，表示两种情况中哪一种都不影响结果。','The departure time stays the same in either case.','不论；无论')],M('The guide asked whether the hikers wanted the west trail or the wetland path, but offered no choice between them.','The guide asked which of the two trails the hikers wanted to take.','A whether-question presents alternatives for a choice.','meaning'),[Q(1,'What did the guide ask the hikers to decide?','Which of two trails to take','Whether a whale is a wheelchair','Where the wind came from','Sense 1 introduces alternatives.','context'),Q(2,'When does the ferry leave?','At six regardless of the wind','Only when the wind is dry','Only when the western trail is open','Sense 2 means the result is unchanged whichever condition applies.','context'),Q(1,'Which pattern is correct?','whether to stay or leave','whether stay and leaving to','whether or stays to leave','Whether commonly introduces alternatives with or.','grammar'),Q(1,'In “Whether or not it rains, we will go,” whether or not means…','the plan is unchanged in either case','the plan depends entirely on rain','the speaker is asking where it rains','The construction expresses independence from either possibility.','meaning')]);
P('which','Which comes from Old English hwilc and asks about a member of a known set, introduces a relative clause, or comments on a preceding statement.',[C('which.s1','group choice','Which of the three western trails crosses the wetland boardwalk?','三条西侧小路中，哪一条穿过湿地栈道？','which one; which of these','疑问限定词，询问已知一组中的一个或多个成员。','The three trails form the known group.','哪一个'),C('which.s2','limited alternatives','Which would you choose, the sturdy wheelchair ramp or the shorter steps?','你会选哪个：结实的轮椅坡道还是更短的台阶？','which of the two; which do you prefer?','疑问代词，从有限选项中询问选哪一个。','The speaker presents two available choices.','哪一个'),C('which.s3','relative clause','The whale, which surfaced beside the research boat, soon disappeared under the waves.','那头在科考船旁浮出水面的鲸很快又消失在浪下。','the animal which…; a tool which works','关系代词，引出补充说明已提到事物的从句。','The clause adds information about the whale.','……的；它'),C('which.s4','clause comment','The wharf closed before sunset, which surprised the visiting westerner.','码头在日落前关闭了，这让来访的西方人感到意外。','…, which was unexpected;…, which means…','关系代词指代前面整件事，并对其作评论。','Which refers to the unexpected closure.','这件事；这')],M('The wharf closed before sunset, which surprised nobody, so all visitors were completely surprised.','The wharf closed before sunset, which surprised the visitors.','The sentence says nobody was surprised and then says everyone was.','meaning'),[Q(1,'Which trail did the question ask about?','The one among three that crosses the boardwalk','Any trail in any country','A trail that has not been mentioned','Sense 1 asks about members of a known group.','context'),Q(2,'What choice is offered in the wheelchair question?','The ramp or the steps','A wheat field or a whale','A western region or a wharf','Sense 2 presents a limited set of alternatives.','context'),Q(3,'What does the which-clause describe?','The whale that surfaced beside the boat','The boat’s weight','The time the sunset began','Sense 3 introduces a clause about a named thing.','context'),Q(4,'What does which refer to in the final sentence?','The wharf closing before sunset','The westerner only','The visitor’s wheelchair','Sense 4 comments on the preceding event.','context')]);
P('whichever','Whichever combines which + ever and means the selected member of a set, with no preference about which one it is.',C('whichever.s1','unrestricted choice','Use whichever wheelchair ramp is open; both entrances reach the library lobby.','哪条轮椅坡道开放就走哪条；两个入口都通向图书馆大厅。','whichever route; choose whichever you prefer','代词或限定词，指一组中任选哪一个都可以。','Either available ramp leads to the same destination.','无论哪一个'),M('Use whichever ramp you like, but only the west entrance has a ramp.','Use the west entrance because it is the only entrance with a ramp.','If only one ramp exists, there is no choice among alternatives.','meaning'),[Q(1,'Which ramp should a visitor use?','Either ramp that is open','Only a nonexistent third ramp','Neither entrance','Whichever leaves the choice open between the two ramps.','context'),Q(1,'“Choose whichever you prefer” means…','the choice may be any one from the set','one exact choice has already been fixed','no choice is permitted','Whichever means it does not matter which member is chosen.','meaning'),Q(1,'Which phrase is grammatical?','whichever route you choose','whichsoever route choose you','whicheverly route you chooses','Whichever modifies route and introduces a choice clause.','grammar'),Q(1,'The library example uses whichever because…','both available ramps lead to the same place','one ramp is forbidden','the destination is unknown','Either option works, so no preference is needed.','context')]);
P('whiff','Whiff is probably imitative of a brief breath or puff; it means a smell that reaches someone suddenly, or to give off/sense a faint smell.',[C('whiff.s1','smell noun','A whiff of wet grass came through the open window after the rain.','雨后，一股湿草气味从开着的窗户飘了进来。','a whiff of smoke/perfume; catch a whiff','名词，指突然闻到的一阵气味。','The smell reaches the person in one brief breath.','一股气味'),C('whiff.s2','smell verb','The kitchen began to whiff of burnt wheat when the pan was left on the stove.','锅留在炉子上后，厨房开始隐约散发出烤焦小麦的气味。','whiff of something; whiff faintly','动词，指散发这种气味或隐约闻到气味。','The kitchen gives off or carries a faint smell.','散发气味；闻到一丝')],M('She caught a whiff of the fresh grass, but her nose detected no smell at all.','She caught a faint smell of the fresh grass through the open window.','Catching a whiff means detecting at least a brief smell.','meaning'),[Q(1,'What came through the window?','A smell of wet grass','A gust of dry wheat','A wheelchair ramp','Sense 1 is a sudden brief smell.','context'),Q(2,'What did the kitchen begin to smell of?','Burnt wheat','Fresh ocean water','A new wharf','Sense 2 is the verb for emitting or sensing a faint smell.','context'),Q(1,'Which phrase is natural?','a whiff of smoke','a whiffly smoke of','whiff to smoke smell','Whiff is followed by of before the smell.','grammar'),Q(1,'Whiff’s origin is best described as…','probably imitative, though not certain','certainly from the Latin for wheel','a compound of wheat + if','The proposed sound imitation is not fully certain.','word-formation')]);
P('while','While comes from Old English hwīl, “a period of time”; it can mark simultaneous events, contrast or concession, a short period, or spending time casually.',[C('while.s1','simultaneous time','While the whale surfaced, the researchers recorded its breathing pattern.','鲸鱼浮出水面时，研究人员记录了它的呼吸规律。','while doing something; while you wait','连词，表示另一件事发生的同时。','The observation happens during the surfacing.','当……时'),C('while.s2','contrast','The western coast is rainy, while the eastern side is comparatively dry.','西海岸多雨，而东侧相对干燥。','while one is…, the other…; while I agree…','连词，用来对照两种事实，也可表示“虽然”。','The two sides have contrasting weather.','而；虽然'),C('while.s3','period','Wait here for a while until the wheelchair ramp is clear.','在这里等一会儿，直到轮椅坡道畅通。','for a while; after a while','名词，指一段时间，尤其是较短的一段。','The visitor waits for a short period.','一会儿'),C('while.s4','pass time','The children whiled away the afternoon drawing whales on the whiteboard.','孩子们在白板上画鲸鱼，轻松地打发了整个下午。','while away the time/day; while away an hour','动词短语，指轻松地消磨时间。','Drawing fills the afternoon in a relaxed way.','消磨时间')],M('The children whiled away the afternoon by refusing to spend any time on an activity.','The children spent the afternoon drawing whales on the whiteboard.','To while away time is to spend it on a relaxed activity.','meaning'),[Q(1,'What happened while the whale surfaced?','Researchers recorded its breathing','The library closed the next day','The tide stopped permanently','Sense 1 marks simultaneous actions.','context'),Q(2,'How do the coasts differ?','The west is rainy and the east drier','Both sides have identical rainfall','The east is a wetland and the west is a wharf','Sense 2 introduces contrast.','context'),Q(3,'How long should the visitor wait?','For a short period','For a whole century','Until the wheat is harvested','Sense 3 is a period of time.','context'),Q(4,'How did the children while away the afternoon?','By drawing on the whiteboard','By refusing every activity','By steering a ship','Sense 4 means pass time casually.','context')]);
P('whilst','Whilst is a historical form related to while and means during the time that something happens, or “although.”',C('whilst.s1','time or contrast','Whilst the tide was low, workers repaired the wharf’s wooden steps.','退潮期间，工人修理了码头的木台阶。','whilst doing something; whilst I agree…','连词，指某事发生期间，也可表示“虽然”。','The repairs take place during low tide.','当……时；虽然'),M('Whilst the tide was low, workers repaired the steps only after the tide had fully risen.','While the tide was low, workers repaired the steps before it rose.','The sentence places the same repair both during low tide and only after it ended.','meaning'),[Q(1,'When did the workers repair the wharf steps?','During low tide','Only after the tide had fully risen','While the western wind stopped forever','Whilst marks the time when the repairs occurred.','context'),Q(1,'Whilst can also mean…','although','at what place','from which source','The source entry includes a concessive use.','meaning'),Q(1,'Which clause is natural?','Whilst I agree with the plan, I have one concern.','Whilst I agreeing the plan, concern one.','I whilst plan have one.','Whilst introduces a full clause.','grammar'),Q(1,'Which word is a close alternative to whilst?','while','wharf','whichever','Whilst is a form meaning during the time that or although.','meaning')]);
P('whim','Whim is probably a shortened form of whimsy, though its history is uncertain; it means a sudden, unimportant wish or an unexpected idea.',[C('whim.s1','impulse','On a whim, Sam took the westbound train instead of following the planned route.','萨姆一时兴起，没按原计划走，而是乘上了向西的火车。','on a whim; act on a whim','名词，指突然冒出的、不太重要的念头或愿望。','The choice is spontaneous and not carefully planned.','一时兴起'),C('whim.s2','unexpected idea','Her latest whim was to paint a tiny whale on every whiteboard in the office.','她最近突发奇想，要在办公室每块白板上画一只小鲸鱼。','a sudden whim; a passing whim','名词，指突然想到的古怪或出人意料的点子。','The idea appears unexpectedly and playfully.','突发奇想')],M('He planned the journey carefully for six months and chose the route on a whim.','He planned the journey carefully for six months and chose the route after careful research.','A decision made after months of planning is not a sudden whim.','meaning'),[Q(1,'How did Sam choose the westbound train?','On a sudden impulse','After following the exact planned route','Because the train was a wheelchair','Sense 1 is an unplanned wish or impulse.','context'),Q(2,'What was the woman’s latest whim?','Painting a tiny whale on each office whiteboard','Building a real wharf','Harvesting wheat in winter','Sense 2 is an unexpected idea.','context'),Q(1,'Which phrase is idiomatic?','on a whim','in a whimly','by whimnessly','The fixed expression is on a whim.','collocation'),Q(1,'The origin of whim is…','uncertain, perhaps shortened from whimsy','certainly from Old English for wheelchair','formed from wharf + -im','The proposed connection is tentative, not certain.','word-formation')]);
P('whimsical','Whimsical is whimsy + -ical and describes playful, fanciful ideas that are unexpected rather than strictly logical.',C('whimsical.s1','creative style','The illustrator filled the children’s book with whimsical whales wearing tiny western hats.','插画家在儿童读物中画了许多戴着小西部帽的奇趣鲸鱼。','whimsical design/story; whimsical sense of humor','形容富有玩趣、奇想而不拘于逻辑的。','The fanciful image is playful and unexpected.','奇趣的'),M('The whimsical illustration was a plain technical diagram with no playful or fanciful details.','The technical illustration was a plain diagram with no playful or fanciful details.','A plain diagram with no fancy elements is not whimsical.','meaning'),[Q(1,'What made the book’s whales whimsical?','They wore tiny western hats','They were shown in a strict scientific diagram','They were all exactly the same size','Whimsical describes fanciful, playful details.','context'),Q(1,'A whimsical idea is usually…','playful and unexpected','strictly routine and predictable','a measurable electric current','The adjective describes fanciful ideas.','meaning'),Q(1,'Which phrase is natural?','a whimsical story','a whimsyly story','a story whimical of','Whimsical is the adjective modifying story.','grammar'),Q(1,'Whimsical is formed from…','whimsy + -ical','whistle + -al','whale + -ism','The suffix -ical forms the adjective from whimsy.','word-formation')]);
P('whine','Whine comes from Old English hwinan, a verb for a whining or whizzing sound; it means cry plaintively, complain irritably, or the sound itself.',[C('whine.s1','cry','The tired child began to whine softly when the long westward drive continued past bedtime.','向西的长途车程过了睡觉时间还没结束，疲倦的孩子开始轻声哭闹。','whine with pain; a child whines','动词，指因痛苦或悲伤发出高而弱的哭声。','The child’s voice is weak and plaintive.','哭闹'),C('whine.s2','complaint','He whined about the wet weather for an hour, although the garden needed rain.','尽管花园需要雨水，他还是抱怨潮湿天气抱怨了一个小时。','whine about something; stop whining','动词，指用令人厌烦的软弱语气抱怨。','He repeatedly complains in an irritating tone.','抱怨'),C('whine.s3','sound noun','A thin whine from the old wheel motor grew louder as the cart climbed the hill.','手推车爬坡时，旧车轮电机发出的细微尖声越来越响。','a high-pitched whine; hear a whine','名词，指高而弱的哭声或机器发出的抱怨似的声音。','The motor makes a thin continuous sound.','尖声；哀鸣')],M('The child whined in a cheerful deep voice because she was happy and full of energy.','The child laughed in a cheerful voice because she was happy and full of energy.','A high, weak, plaintive sound is a whine, not a cheerful laugh.','meaning'),[Q(1,'Why did the tired child whine?','The drive continued past bedtime','She had just finished a short nap','The whale had surfaced','Sense 1 is a weak, plaintive cry.','context'),Q(2,'What did the man complain about?','The wet weather','The wheel’s size only','The western region’s wheat crop','Sense 2 means complain in an irritating voice.','context'),Q(3,'What made the thin whine?','The old wheel motor','The quiet wharf','The soft wheat grain','Sense 3 is the sound noun.','context'),Q(1,'Which phrase is natural?','whine about the delay','whine the delayly','whine to the delay about of','Whine about is the common complaint construction.','grammar')]);
P('whip','Whip is an English word of uncertain origin; it names a lash, hitting with one, beating cream quickly, or a party official who enforces voting discipline.',[C('whip.s1','tool','The rider hung the leather whip on the stable wall and never used it on the horse.','骑手把皮鞭挂在马厩墙上，从不拿它抽打马匹。','leather whip; crack a whip','名词，指细长的皮革或绳索鞭子。','The long narrow tool is made of leather.','鞭子'),C('whip.s2','strike','The old law forbade guards to whip prisoners as a punishment.','旧法禁止看守用鞭子抽打囚犯作为惩罚。','whip someone; whip with a cord','动词，指用鞭子抽打人或动物。','The action is a strike with a whip.','鞭打'),C('whip.s3','food preparation','Whip the cream until it holds soft peaks, then spoon it over the wheat pudding.','把奶油打发到能立起柔软尖峰，再舀在小麦布丁上。','whip cream/eggs; whipped cream','动词，指快速搅打奶油或鸡蛋使其变稠。','Rapid beating thickens the cream.','搅打'),C('whip.s4','politics','The party whip reminded members to attend the vote and support the agreed bill.','党鞭提醒成员参加表决并支持已商定的法案。','party whip; chief whip','名词，指负责督促党内成员按党派要求投票的官员。','The official organizes attendance and party voting.','党鞭')],M('The party whip instructed members to ignore the party’s position and miss the vote.','The party whip instructed members to follow the party’s position and attend the vote.','A party whip enforces voting discipline, not indifference to it.','meaning'),[Q(1,'What did the rider hang on the stable wall?','A leather whip','A wheat stalk','A wheelchair ramp','Sense 1 is the long narrow tool.','context'),Q(2,'What did the old law forbid guards to do?','Strike prisoners with a whip','Beat cream for pudding','Attend the vote','Sense 2 uses whip as a verb.','context'),Q(3,'How should the cream be prepared?','Whipped until it holds soft peaks','Left untouched until it freezes','Welded to the bowl','Sense 3 means beat quickly until thick.','context'),Q(4,'What does the party whip do?','Encourages members to attend and follow the vote','Makes cream for the meeting','Builds the party’s wharf','Sense 4 is the political official.','context')]);
P('whir','Whir is imitative of a low continuous mechanical or wing sound; as a noun it names the sound and as a verb it means make that sound.',[C('whir.s1','sound','The quiet whir of the wheelchair’s motor grew louder as it climbed the ramp.','轮椅爬坡时，电机轻柔的持续嗡嗡声变得更响。','a low whir; hear the whir of a fan','名词，指快速转动的机器或翅膀发出的低沉连续声。','The motor makes the sustained sound.','嗡嗡声'),C('whir.s2','sound verb','The small fan whirred all night above the bed.','小风扇整夜在床上方嗡嗡作响。','a motor whirs; whir quietly','动词，指发出类似快速转动的连续低声。','The rotating fan produces the sound.','嗡嗡作响')],M('The fan whirred silently, making a loud continuous mechanical sound all night.','The fan whirred loudly, making a continuous mechanical sound all night.','A loud sound cannot simultaneously be silent.','meaning'),[Q(1,'What grew louder on the ramp?','The wheelchair motor’s whir','The sound of wheat being harvested','A whale’s call beneath the ocean','Sense 1 is the sound noun.','context'),Q(2,'What did the small fan do all night?','It whirred','It stopped and made no sound','It turned into a wharf','Sense 2 uses whir as a verb.','context'),Q(1,'A whir is usually…','a low continuous sound from something turning fast','a single loud explosion','a person’s formal vote','The sound is sustained and mechanical-like.','meaning'),Q(1,'Which phrase is natural?','the whir of a fan','a fan whirly of','the whirringly of fan','Whir is used as a noun with of to name its source.','grammar')]);
P('whirl','Whirl is probably related to Old Norse hvirfla, “turn around”; it can mean spin rapidly, feel mentally dizzy, a spinning movement, or a busy sequence.',[C('whirl.s1','spin','The dancers whirled across the floor while the orchestra played a fast tune.','乐队演奏快曲时，舞者在地板上飞旋。','whirl around; whirl something in a circle','动词，指快速旋转或使某物旋转。','The dancers turn rapidly across the floor.','旋转'),C('whirl.s2','dizziness','After reading tiny print in the moving bus, the numbers seemed to whirl in her mind.','在行驶的公交车上读完小字后，那些数字仿佛在她脑中打转。','make one’s head whirl; thoughts whirl','动词，指感到头脑像在旋转、眩晕。','The person feels mentally dizzy.','头晕；混乱'),C('whirl.s3','spinning motion','One quick whirl of the wheel sent the cart rolling down the lane.','车轮快速转了一圈，手推车便沿小路滚了下去。','a whirl of activity; a quick whirl','名词，指快速旋转的动作。','The word names one spinning movement.','旋转'),C('whirl.s4','busy events','The first week of the festival was a whirl of rehearsals, interviews, and late-night shows.','节庆第一周忙得团团转，排练、采访和深夜演出接连不断。','a whirl of events/activity; a social whirl','名词，比喻忙乱而接连不断的一系列活动。','Many events happen rapidly in succession.','忙乱的一连串活动')],M('The dancers whirled across the floor by standing perfectly still throughout the fast tune.','The dancers moved across the floor by spinning to the fast tune.','Standing still is not whirling.','meaning'),[Q(1,'What did the dancers do across the floor?','Spun rapidly','Stood motionless','Wheeled crates to the wharf','Sense 1 is rapid turning.','context'),Q(2,'Why did the numbers seem to whirl in her mind?','The moving bus made her feel dizzy','She was asleep at home','The numbers had been welded together','Sense 2 describes a spinning mental feeling.','context'),Q(3,'What sent the cart rolling?','One quick turn of the wheel','A long period of well-being','A wheat grain','Sense 3 is a spinning movement.','context'),Q(4,'What filled the festival’s first week?','A busy series of events','A single quiet afternoon','An empty wharf','Sense 4 is a rapid, confusing sequence of activities.','context')]);
P('whirlpool','Whirlpool combines whirl + pool and names water moving in a circle with a downward pull in a river or sea.',C('whirlpool.s1','water current','The small boat drifted away from the whirlpool before the rotating current could pull it inward.','小船在旋转水流把它卷进去之前，驶离了漩涡。','a dangerous whirlpool; a whirlpool forms','名词，指河流或海中带有向下牵引力的旋转水流。','The current circles and pulls objects inward.','漩涡'),M('The boat drifted toward the whirlpool, where the water flowed calmly in straight lines without any pull.','The boat drifted away from the whirlpool, whose circular current pulled inward.','A whirlpool has circulating water and a downward pull, not a calm straight flow.','meaning'),[Q(1,'What did the boat avoid?','A rotating current that could pull it inward','A dry wheat field','A westward gust only','Sense 1 describes the water vortex.','context'),Q(1,'Where can a whirlpool form?','In a river or the sea','Only in a paperweight','Only in dry land','The source definition locates it in moving water.','meaning'),Q(1,'Which phrase is natural?','a dangerous whirlpool','a whirlpool of wind only','whirlpoolly current','Whirlpool names a rotating water current.','collocation'),Q(1,'The compound joins…','whirl + pool','wharf + west','whistle + pole','The name combines spinning motion and a body of water.','word-formation')]);
P('whirlwind','Whirlwind is whirl + wind, probably modeled on Old Norse hvirfilvindr; it means a rapidly spinning air column or, figuratively, a short burst of intense activity.',[C('whirlwind.s1','weather','A narrow whirlwind lifted dust over the field and twisted the dry stalks into the air.','一股狭窄的旋风卷起田野上的尘土，把干燥的茎秆卷上空中。','a whirlwind sweeps through; dust whirlwind','名词，指快速旋转的狭长气柱。','The air spins rapidly over land.','旋风'),C('whirlwind.s2','rapid activity','The young actor’s life became a whirlwind of interviews and travel after the film opened.','电影上映后，年轻演员的生活被采访和旅行的忙碌旋风席卷。','a whirlwind of activity; whirlwind tour','比喻短时间内大量快速发生的活动。','Many events happen in quick succession.','忙碌的一阵')],M('A whirlwind crossed the field as a calm, motionless column of air with no rotation.','A still column of air crossed the field without forming a whirlwind.','A whirlwind is defined by its rapid rotation.','meaning'),[Q(1,'What did the weather whirlwind lift?','Dust and dry stalks','The wheel from the boat','Wheat flour from the mill only','Sense 1 is a rotating air column.','context'),Q(2,'What made the actor’s schedule a whirlwind?','Interviews and travel quickly followed the film opening','The actor had no work for a year','One quiet afternoon passed','Sense 2 is figurative intense activity.','context'),Q(1,'A whirlwind tour is…','a very busy series of visits in a short time','a calm trip with no stops','a ride inside a whirlpool','The figurative sense suggests rapid activity.','meaning'),Q(1,'The word whirlwind combines…','whirl + wind','whisky + land','while + hand','The compound names spinning air.','word-formation')]);
P('whisk','Whisk comes from Old Norse visk, “a wisp or sweeping tool”; it can take someone away suddenly, beat or brush quickly, or name a wire-loop kitchen tool.',[C('whisk.s1','move quickly','The nurse whisked the patient away from the crowded wharf to a quiet room.','护士迅速把病人从拥挤的码头带到安静的房间。','whisk someone away; whisk a child off','动词，指迅速而突然地带走某人或某物。','The movement is sudden and quick.','迅速带走'),C('whisk.s2','beat/brush','Whisk the eggs briskly, then whisk a crumb from the whiteboard with your sleeve.','快速搅打鸡蛋，然后用袖子轻轻拂掉白板上的面包屑。','whisk eggs/cream; whisk something away','动词，指快速搅打食物或轻轻扫去东西。','The first action beats; the second sweeps lightly.','搅打；拂去'),C('whisk.s3','kitchen tool','She used a small wire whisk to beat the cream until it became thick.','她用小钢丝打蛋器把奶油搅打到变稠。','wire whisk; balloon whisk','名词，指由环形金属丝制成、用于搅打鸡蛋或奶油的工具。','The tool’s loops whip air into the cream.','打蛋器')],M('She whisked the patient away slowly over several days, without moving him from the waiting room.','She moved the patient away quickly to a quiet room.','Whisk someone away describes a sudden quick removal.','meaning'),[Q(1,'Where did the nurse take the patient?','Quickly to a quiet room','Slowly across the ocean','Into the western wind','Sense 1 means take away suddenly.','context'),Q(2,'What did the cook do to the eggs?','Beat them briskly','Leave them whole and untouched','Weld them to the pan','Sense 2 includes fast beating.','context'),Q(3,'What tool did she use on the cream?','A wire whisk','A ship’s wheel','A paper weight','Sense 3 names the kitchen implement.','context'),Q(1,'Which phrase is standard?','whisk someone away','whisk someone awayly into','whisk to someone the away','The phrasal verb uses whisk + object + away.','grammar')]);
P('whiskey','Whiskey comes from Gaelic uisge beatha, “water of life,” through forms in Irish or Scottish Gaelic; the spelling whiskey is especially Irish and American.',C('whiskey.s1','drink','The label identifies the bottle as Irish whiskey distilled from malted grain.','标签说明这瓶酒是用麦芽谷物蒸馏的爱尔兰威士忌。','Irish/American whiskey; a glass of whiskey','名词，指用麦芽谷物蒸馏制成的烈酒，尤其见于爱尔兰或美国拼法。','The drink is a distilled spirit.','威士忌'),M('The label called the bottle Irish whiskey, but it contained only plain spring water.','The label called the bottle Irish whiskey, a spirit distilled from grain.','Plain water is not a distilled grain spirit.','meaning'),[Q(1,'What did the label identify?','Irish whiskey distilled from malted grain','A bottle of plain spring water','A wheat field in the West','The source sense is a distilled alcoholic spirit.','context'),Q(1,'What does the Gaelic phrase uisge beatha literally mean?','Water of life','West wind','Whirlpool of grain','The phrase literally means water of life.','word-formation'),Q(1,'The spelling whiskey is especially associated with…','Irish and American usage','only British place names','westerly winds','The spelling distinction is especially used for Irish and American forms.','usage'),Q(1,'Which phrase is natural?','a glass of whiskey','a whiskey of wheatly','whiskey the glass to','Whiskey is a countable drink noun in this phrase.','grammar')]);
P('whisky','Whisky is the Scottish spelling of the Gaelic-derived spirit name uisge beatha, “water of life”; it names the drink or a glass/measure of it.',[C('whisky.s1','drink','The distillery ages its single-malt whisky in oak barrels for twelve years.','这家酿酒厂把单一麦芽威士忌放在橡木桶中陈酿十二年。','Scotch whisky; malt whisky','名词，指用谷物蒸馏制成的烈酒，常见于苏格兰拼法。','The liquid is a grain spirit aged in barrels.','威士忌'),C('whisky.s2','serving','He ordered a whisky after dinner and sipped it slowly beside the fireplace.','晚饭后，他点了一杯威士忌，在壁炉旁慢慢啜饮。','a glass/measure of whisky; order a whisky','名词，指一杯或一份这种烈酒。','The article a counts one serving.','一杯威士忌')],M('The distillery bottled Scotch whisky, but the bottle contained only unfermented wheat flour.','The distillery bottled Scotch whisky, a spirit distilled from grain.','Flour is not a distilled alcoholic drink.','meaning'),[Q(1,'How long was the single-malt whisky aged?','Twelve years','One evening','Until the wheat sprouted','Sense 1 is the alcoholic drink.','context'),Q(2,'What did he order after dinner?','One serving of whisky','A whole oak barrel','A wheel for the fireplace','Sense 2 counts a glass or measure.','context'),Q(1,'Which spelling is especially associated with Scotland?','whisky','whiskey only','whiskey','The source notes a spelling difference for Scotch whisky.','spelling'),Q(1,'The name is ultimately associated with Gaelic…','uisge beatha, “water of life”','hwǣr, “where”','hvirfla, “turn”','The drink name comes from a Gaelic phrase meaning water of life.','word-formation')]);
P('whisper','Whisper comes from Old English hwisprian; it can mean speak in a breathy low voice, spread something privately, the quiet words, or a rumor passed quietly.',[C('whisper.s1','quiet speech','The librarian whispered the room number so the sleeping child would not wake.','图书管理员低声说出房间号，以免吵醒熟睡的孩子。','whisper softly; whisper to someone','动词，指用气声或极轻的声音说话。','The speaker keeps the volume very low.','低声说'),C('whisper.s2','private suggestion','Several traders whispered that the old wharf might close before the winter storms.','几名商贩私下传说旧码头可能会在冬季风暴前关闭。','whisper that…; whisper a rumor','动词，指私下说或暗示某事，使传闻流传。','The information is shared quietly as a rumor.','私下传说'),C('whisper.s3','quiet words noun','I heard a whisper from the back row but could not make out the words.','我听见后排有人低语，却听不清说了什么。','speak in a whisper; a faint whisper','名词，指极轻声说出的言语。','The sound is too quiet to understand clearly.','低语'),C('whisper.s4','rumor noun','A whisper about layoffs spread through the office before management made an announcement.','管理层发布公告前，有关裁员的传言已在办公室里悄悄传开。','a whisper of trouble; hear whispers that…','名词，指私下流传的消息或传闻。','The news moves quietly between people.','传闻')],M('The librarian whispered the room number by shouting it across the silent room.','The librarian said the room number in a very low voice.','Shouting is the opposite of whispering.','meaning'),[Q(1,'How did the librarian give the room number?','In a very low voice','By shouting across the room','By writing it on a wheat stalk','Sense 1 is quiet speech.','context'),Q(2,'What did traders whisper about the wharf?','That it might close before winter storms','That it had already become a whale','That wheat could not grow anywhere','Sense 2 means quietly suggesting or spreading news.','context'),Q(3,'What did the listener hear from the back row?','A quiet utterance','A loud whistle','A full speech from the stage','Sense 3 is the quiet words themselves.','context'),Q(4,'What spread through the office?','A quiet rumor about layoffs','A formal vote','A glass of whisky','Sense 4 is a rumor passed privately.','context')]);
P('whistle','Whistle is from Old English hwistlian, an imitative word for a high sound; it can mean make that sound with lips, a device, steam, or wind, the device, or its sound.',[C('whistle.s1','lips','The referee whistled sharply through her lips to stop play near the wharf.','裁判用嘴唇尖锐地吹哨，叫停码头附近的比赛。','whistle a tune; whistle through one’s teeth','动词，指通过嘴唇吹出高而悦耳的声音。','Air through the lips produces the high note.','吹口哨'),C('whistle.s2','sound source','Wind whistled through the narrow gap beneath the white door all night.','整夜，风从白门下方的窄缝中呼啸而过。','wind/steam whistles; whistle past','动词，指装置、蒸汽或风发出高音。','Air rushing through the gap makes the sound.','呼啸'),C('whistle.s3','device','The guard carried a small whistle in case anyone needed help on the wetland path.','守卫带着一个小哨子，以防有人在湿地小路上需要帮助。','blow/use a whistle; referee’s whistle','名词，指吹气即可发出高音的小装置。','The object is used to signal by blowing.','哨子'),C('whistle.s4','sound noun','The whistle of the kettle announced that the water was boiling.','水壶发出的尖鸣声提示水已经烧开。','a shrill whistle; hear a whistle','名词，指高而清晰的声音。','The sound signals boiling water.','尖鸣声')],M('The guard used a whistle by holding the silent device without blowing it to signal for help.','The guard blew the whistle to signal for help.','A silent unblown whistle does not produce its signaling sound.','meaning'),[Q(1,'How did the referee stop play?','By whistling through her lips','By whispering the score','By turning the ship’s wheel','Sense 1 means making a note with the lips.','context'),Q(2,'What made a high sound beneath the door?','Wind rushing through the gap','A voter casting a ballot','A whale chewing wheat','Sense 2 includes wind making the sound.','context'),Q(3,'What did the guard carry?','A small sound-making device','A whiteboard','A paperweight','Sense 3 is the device itself.','context'),Q(4,'What announced that the water was boiling?','The kettle’s high clear sound','A written whisper','A westward sign','Sense 4 names the sound.','context')]);
P('whit','Whit is an old English word for a very small amount, now used almost only in the negative phrase “not a whit.”',C('whit.s1','small amount','The new evidence did not change the verdict one whit, because it repeated facts already known.','新证据一点也没改变判决，因为它只是重复了已知事实。','not a whit; not care a whit','名词，指极小的数量，几乎只用于否定表达。','The verdict changed by no amount at all.','一点；丝毫'),M('The new evidence changed the verdict not a whit, completely reversing the decision.','The new evidence changed the verdict substantially, completely reversing the decision.','“Not a whit” means not at all, which conflicts with a complete reversal.','meaning'),[Q(1,'How much did the evidence change the verdict?','Not at all','It reversed the decision completely','It changed the western region','Whit means a very small amount and appears here with not.','context'),Q(1,'Which expression is conventional?','not a whit','a whitly lot','whit of the westward','The word is used almost only in the phrase not a whit.','collocation'),Q(1,'In “I don’t care a whit,” whit means…','the smallest amount','a large number','a sound made by wind','The idiom denies caring even a tiny bit.','meaning'),Q(1,'Whit is best described as…','a rare word for a tiny amount','a common verb meaning to welcome','a kind of wheelchair','The source defines whit as a very small amount.','meaning')]);
P('white','White comes from Old English hwīt; it names a color, a racial category in description, pallor from emotion or illness, or the clear part of an egg/eye.',[C('white.s1','color','The crew painted the white buoy bright orange so ships could see it in fog.','船员把白色浮标漆成鲜橙色，让船只在雾中看得见。','white paint; a white shirt','形容雪、牛奶或盐的颜色。','The buoy originally had the color white.','白色的'),C('white.s2','demographic description','The census form records whether respondents identify as white as one of several racial categories.','人口普查表会记录受访者是否自我认同为白人，作为多个种族类别之一。','white population; identify as white','在种族描述中，指肤色较浅的人群类别。','The context uses a neutral demographic classification.','白人的'),C('white.s3','pallor','Her face went white when she heard that the ferry had lost power in the storm.','听说渡船在风暴中失去动力后，她的脸吓得发白。','go/turn white; white with fear','形容因恐惧、愤怒或疾病而脸色苍白。','Fear drains color from her face.','苍白的'),C('white.s4','egg/eye part','Separate the egg white from the yolk before whisking it into a foam.','搅打成泡沫之前，先把蛋清和蛋黄分开。','egg white; the white of the eye','名词，指蛋清或眼球的白色部分。','The clear albumen is separated from the yolk.','蛋清；眼白')],M('The white buoy was painted the color of coal so ships could see it clearly in fog.','The white buoy was painted bright orange so ships could see it clearly in fog.','Coal is black, not white; the correction gives a visible bright color.','meaning'),[Q(1,'What color was the buoy before it was repainted?','White','Bright orange','Black coal','Sense 1 is the color.','context'),Q(2,'What does the census form record?','Whether a respondent identifies as white','The respondent’s wheat crop','The color of every boat','Sense 2 is a demographic description.','context'),Q(3,'Why did her face go white?','She was frightened by the ferry problem','She had just painted a buoy','She was choosing a racial category','Sense 3 is pallor caused by fear.','context'),Q(4,'What should be separated from the yolk?','The egg white','The egg shell only','The whiteboard marker','Sense 4 names the clear part of an egg.','context')]);
P('white-haired','White-haired combines white + hair + -ed and describes hair that has turned white or grey, usually with age.',C('white-haired.s1','appearance','The white-haired gardener moved carefully among the young wheat plants.','这位白发园丁在幼小的麦苗间小心地走动。','white-haired woman/man; a white-haired elder','形容头发已变白或灰白，通常与年老有关。','The gardener’s hair has lost its darker color.','白发的'),M('The white-haired gardener had uniformly jet-black hair with no grey strands.','The dark-haired gardener had uniformly jet-black hair with no grey strands.','Jet-black hair is not white-haired.','meaning'),[Q(1,'What distinguished the gardener’s appearance?','Her hair had turned white or grey','She wore a whiteboard marker','She had wheat-colored clothes','White-haired describes hair color.','context'),Q(1,'White-haired usually describes someone whose hair…','has become white or grey','is naturally green','has been covered by rain','The source associates the description commonly with age.','meaning'),Q(1,'Which phrase is correctly hyphenated before a noun?','a white-haired gardener','a white hairedly gardener','a hair-white gardeners','The compound adjective takes hyphens before the noun.','grammar'),Q(1,'White-haired is built from white + hair +…','-ed','-ness','-ward','The ending forms an adjective describing a state.','word-formation')]);
P('whiteboard','Whiteboard combines white + board and names a smooth white writing surface used with special markers.',C('whiteboard.s1','classroom','The teacher wrote the three trail choices on the whiteboard with a blue dry-erase marker.','老师用蓝色白板笔把三条小路选项写在白板上。','write on a whiteboard; erase a whiteboard','名词，指用专用记号笔书写、可擦除的光滑白色板面。','The marker writes on the board and can be erased.','白板'),M('The teacher wrote on the whiteboard with permanent ink that could never be erased.','The teacher wrote on the whiteboard with an erasable dry-erase marker.','A standard whiteboard is used with special erasable markers.','collocation'),[Q(1,'What did the teacher write on the board?','Three trail choices','The history of whiskey','The weight of the building','The whiteboard was used for classroom notes.','context'),Q(1,'What is a whiteboard?','A smooth white surface for marker writing','A wall painted with whitewash only','A kind of wheat grain','Its defining use is writing with special markers.','meaning'),Q(1,'Which tool is designed for a whiteboard?','A dry-erase marker','A permanent welding torch','A leather whip','Special markers are used on the white surface.','context'),Q(1,'Which verb naturally goes with whiteboard?','erase','whittle into a drink','wade across','Writing on a whiteboard is commonly erased afterward.','collocation')]);
P('whiten','Whiten is white + -en and means make something white or become white/pale.',[C('whiten.s1','transitive','The cleaner used sunlight to whiten the cotton curtains without harsh chemicals.','清洁人员用日光把棉窗帘漂白，没有使用刺激性化学品。','whiten teeth/cloth; whiten something','及物动词，指使某物变白或更白。','The sunlight makes the curtains lighter.','使变白'),C('whiten.s2','intransitive','The paint began to whiten as it dried on the fresh plaster wall.','新灰泥墙上的油漆变干时开始泛白。','clouds whiten; whiten with age','不及物动词，指自己变白或变得苍白。','The color changes as the paint dries.','变白')],M('The cleaner whitened the curtains by turning the cotton a deeper black.','The cleaner darkened the curtains by turning the cotton a deeper black.','Turning something black darkens it; it does not whiten it.','meaning'),[Q(1,'What did the sunlight do to the curtains?','Made them whiter','Turned them black','Made them wet forever','Sense 1 is the transitive action.','context'),Q(2,'What happened as the paint dried?','It became white','It turned into a whiteboard','It began to whistle','Sense 2 describes something becoming white.','context'),Q(1,'Which construction is correct?','whiten the cloth','whiten to the cloth','whitenly the cloth','Whiten takes the object that becomes white.','grammar'),Q(1,'The suffix -en in whiten means…','make or become','without','a person who does something','The suffix forms a verb meaning make/become white.','word-formation')]);
P('whiteware','Whiteware combines white + ware and names white ceramic goods, including sanitary fittings, and some white household appliances.',[C('whiteware.s1','household goods','The showroom displayed whiteware such as sinks, ceramic basins, and refrigerators.','展厅展示了白色家居用品，例如水槽、陶瓷洗手盆和冰箱。','bathroom whiteware; whiteware appliance','名词，指白色陶瓷器具，也可指冰箱等白色家电。','The items are household fixtures or appliances.','白色家居用品')],M('The showroom classified the refrigerator as whiteware even though it was a live whale.','The showroom classified the refrigerator as whiteware, a household appliance.','A whale is not a domestic appliance or ceramic fitting.','meaning'),[Q(1,'Which items did the showroom display?','Sinks, basins, and refrigerators','Whales, wheat, and westerlies','Only leather whips','These are examples of whiteware goods.','context'),Q(1,'Whiteware can include…','white ceramic fittings and household appliances','only white writing boards','a wind from the west','The source covers ceramics and major appliances.','meaning'),Q(1,'Which collocation is natural?','bathroom whiteware','whiteware of a whale','whitewarely sink','Whiteware is a category for fixtures such as sinks.','collocation'),Q(1,'Whiteware combines…','white + ware','whistle + wear','west + wheat','The compound names a class of pale household goods.','word-formation')]);
P('whitewash','Whitewash combines white + wash and names a lime-and-water wall coating; as a verb it can apply that coating or figuratively conceal failure or wrongdoing.',[C('whitewash.s1','literal and figurative','Workers covered the garden wall with whitewash, while the report whitewashed the contractor’s safety failures.','工人用白色涂料刷墙，而报告则掩盖了承包商的安全失误。','apply whitewash; whitewash a failure/scandal','名词指刷白墙面的灰浆，也可作动词，指用涂料刷白或掩盖过失。','The literal coating covers the wall; the figurative use hides blame.','白墙涂料；掩盖')],M('The report whitewashed the safety failures by listing every incident and naming those responsible.','The report exposed the safety failures by listing every incident and naming those responsible.','Full disclosure exposes wrongdoing instead of concealing it.','meaning'),[Q(1,'What did workers use on the garden wall?','A lime-based white coating','A leather whip','A bottle of whisky','Whitewash is a wall coating.','context'),Q(1,'What did the report do figuratively?','Concealed the contractor’s failures','Published every detail and exposed them','Painted the wall white','The figurative sense means cover up wrongdoing.','context'),Q(1,'Which phrase is natural?','whitewash a scandal','whitewash the scandal openly by exposing all evidence','a whitewashed of walling','Whitewash can mean conceal a scandal.','collocation'),Q(1,'The word is formed from…','white + wash','whistle + ash','wharf + wheat','The literal compound describes washing or coating a surface white.','word-formation')]);
P('whittle','Whittle comes from Old English þwitan, “to cut,” through a Middle English knife name; it means shave wood with a knife or reduce something gradually.',[C('whittle.s1','woodworking','By the fire, Luis whittled a willow branch into a smooth handle with a small pocketknife.','路易斯在火边用小刀把柳枝削成光滑的把手。','whittle wood; whittle a stick into shape','动词，指用刀削木头，也可比喻逐渐削减数量。','The knife removes thin shavings from the branch.','削木'),C('whittle.s1','reduction','The department whittled its travel budget down by cutting unnecessary trips.','部门通过削减不必要的出差，逐步缩减了旅行预算。','whittle down costs; whittle away at a budget','动词，比喻逐渐减少数量或规模。','Repeated cuts make the budget smaller.','逐步削减')],M('Luis whittled the branch by attaching extra chips of wood until it grew longer.','Luis whittled the branch by shaving thin chips from it until it became smooth.','Whittling removes small pieces; it does not add them.','meaning'),[Q(1,'What did Luis make from the willow branch?','A smooth handle','A whole number','A whitewash coating','He shaped the wood by shaving it with a knife.','context'),Q(1,'How did the department reduce its budget?','By cutting unnecessary trips','By adding more trips','By buying a new whisky glass','Whittle down is the figurative sense of gradual reduction.','context'),Q(1,'Which phrase is natural?','whittle a stick into shape','whittle a stick into longer','whittlely the wood','The verb can take the material as object and describe shaping it.','grammar'),Q(1,'The historical root þwitan meant…','to cut','to be healthy','to ask which person','Whittle descends from an Old English verb meaning cut.','word-formation')]);
P('who','Who comes from Old English hwā and asks which person, identifies a person, or introduces information about a person already mentioned.',[C('who.s1','question subject','Who repaired the whiteboard before the meeting began?','会议开始前是谁修好了白板？','who did it?; ask who arrived','疑问代词，询问做某事的人。','The speaker asks for the person performing the action.','谁'),C('who.s2','relative clause','The westerner who guided us across the wetland knew every safe boardwalk.','带我们穿过湿地的那位西方人熟悉每一条安全栈道。','the person who…; anyone who…','关系代词，引出关于已提到人物的补充信息。','The clause identifies which westerner guided them.','……的人'),C('who.s3','identity','I recognized the voice, but I could not remember who was calling from the wharf.','我认出了那个声音，却想不起码头打来电话的人是谁。','know/remember who; who is that?','疑问代词，询问或确认某人的身份。','The speaker seeks the caller’s identity.','是谁')],M('Who repaired the whiteboard? The answer was a tool, not a person.','Which tool repaired the whiteboard? The answer was a tool, not a person.','Who asks for a person; a tool is identified with which/what.','meaning'),[Q(1,'What does the first question ask for?','The person who repaired the board','The color of the board','The weight of the marker','Sense 1 asks which person performed an action.','context'),Q(2,'What does the who-clause tell us about the westerner?','He guided the group across the wetland','He painted a whiteboard','He bought a glass of whisky','Sense 2 introduces information about a person.','context'),Q(3,'What could the speaker not remember?','The caller’s identity','The exact time of sunset','The number of wheels','Sense 3 asks who the caller was.','context'),Q(1,'Which question correctly asks about a person?','Who repaired the board?','Where repaired the board?','How repaired the board?','Who is used for a person’s identity or role.','grammar')]);
P('whoever','Whoever combines who + ever and means the person who, or no matter which person.',[C('whoever.s1','any person','Whoever arrives first should unlock the whiteboard room and switch on the lights.','无论谁先到，都应该打开白板室并开灯。','whoever arrives; give it to whoever asks','代词，指做某事的那个人，或不论哪个人。','The instruction applies to any person who arrives first.','无论谁')],M('Whoever arrives first should unlock the room, but nobody who arrives is allowed to open it.','Whoever arrives first should unlock the room; the instruction applies to that person.','The sentence gives and then denies the same person permission.','meaning'),[Q(1,'Who should unlock the whiteboard room?','The first person to arrive','Only the last person to leave','The person who painted the wall','Whoever refers to any person meeting the condition.','context'),Q(1,'“Give the key to whoever asks” means…','give it to any person who asks','give it only to one named person','keep it from everyone','Whoever introduces an unrestricted person.','meaning'),Q(1,'Which sentence is grammatical?','Whoever finishes first may leave.','Whoever finish first may leaves.','Whoever first finishing may leave it.','The singular whoever takes a singular verb.','grammar'),Q(1,'Whoever is formed from…','who + ever','whole + ever','wharf + -er','The compound makes the person reference unrestricted.','word-formation')]);
P('whole','Whole comes from Old English hāl, “entire, unhurt, healthy”; it means all parts, unbroken, or the entire thing taken together.',[C('whole.s1','complete amount','She spent the whole afternoon repairing the old whiteboard instead of taking a break.','她整个下午都在修旧白板，没有休息。','the whole day; whole amount','形容全部的、没有遗漏部分的。','The afternoon from beginning to end is included.','整个的'),C('whole.s2','unbroken','The ceramic bowl remained whole after it fell onto the padded floor.','陶瓷碗掉在铺了垫子的地板上后仍然完好无损。','in one whole piece; keep something whole','形容完整无损、没有破裂或分割。','The bowl did not break.','完整的'),C('whole.s3','entire thing','The committee considered the project as a whole before approving the budget.','委员会在批准预算前把整个项目作为一个整体来考虑。','the whole of something; as a whole','名词或短语，指所有部分合起来的整体。','The project is viewed collectively.','整体')],M('The ceramic bowl remained whole after it shattered into several pieces on the floor.','The ceramic bowl was broken after it shattered into several pieces on the floor.','An object shattered into pieces is no longer whole.','meaning'),[Q(1,'What did she spend repairing the board?','The entire afternoon','Only one minute','The afternoon’s weight','Sense 1 means all of a period.','context'),Q(2,'What happened to the ceramic bowl?','It remained unbroken','It shattered into pieces','It became a whiteboard','Sense 2 means intact.','context'),Q(3,'How did the committee consider the project?','As an entire thing','As a single damaged bowl','Only as a list of unrelated parts','Sense 3 treats all parts together.','context'),Q(1,'Which phrase is natural?','the whole afternoon','the wholely afternoon','afternoon of wholes','Whole means entire and modifies afternoon.','grammar')]);
P('whole number','Whole number combines whole + number and names an integer such as zero, one, or two, with no fractional or decimal part.',C('whole number.s1','mathematics','The answer must be a whole number, so 3.5 is not allowed in this exercise.','答案必须是整数，因此这道题不允许写3.5。','positive whole number; whole-number answer','名词，指没有小数或分数部分的整数，包括零。','The answer has no decimal part.','整数'),M('The teacher accepted 3.5 as a whole number even though it contains a fractional part.','The teacher accepted 3 as a whole number because it has no fractional part.','A decimal such as 3.5 is not an integer.','meaning'),[Q(1,'Why was 3.5 rejected?','It has a fractional part','It is the number zero','It is a whiteboard','A whole number has no fractional or decimal part.','context'),Q(1,'Which is a whole number?','0','2.75','one half','Zero is an integer with no fractional part.','meaning'),Q(1,'Which phrase is standard?','a whole number','a number wholely','a wholely number','The established mathematical term is whole number.','collocation'),Q(1,'Whole number refers to…','an integer such as zero, one, or two','any decimal measurement','a number written only in words','The source definition gives integers without fractions.','meaning')]);
P('wholeness','Wholeness is whole + -ness and means the state of being complete, with all parts present and nothing missing.',C('wholeness.s1','completeness','Restoring the missing panel gave the mural a sense of wholeness again.','补回缺失的画板后，这幅壁画又显得完整了。','a sense of wholeness; restore wholeness','名词，指所有部分齐全、没有缺失的状态。','The restored panel completes the mural.','完整性'),M('The mural’s wholeness depended on a panel that was permanently missing.','The mural’s wholeness returned when the missing panel was restored.','A missing part means the mural is incomplete.','meaning'),[Q(1,'What restored the mural’s wholeness?','Replacing the missing panel','Removing another panel','Painting over the whole mural','Wholeness is the state of completeness.','context'),Q(1,'Wholeness means…','being complete with nothing missing','being split into separate pieces','being very wealthy','The noun names the quality of being whole.','meaning'),Q(1,'Which phrase is natural?','a sense of wholeness','a wholenessly sense','whole of a ness','Wholeness is the noun following sense of.','grammar'),Q(1,'The suffix -ness turns whole into…','a noun for a state or quality','a verb meaning to cut wood','a person noun','-ness forms an abstract noun from the adjective.','word-formation')]);
P('wholesale','Wholesale is whole + sale; it means selling or buying goods in bulk for trade, can describe bulk commerce, an extensive change, or selling to businesses.',[C('wholesale.s1','commerce','Wholesale trade supplied crates of whiteware to neighborhood shops.','批发商买下几箱白色家居用品，准备转售给附近商店。','wholesale trade; wholesale business','名词，指把大量商品卖给商店等零售商的批发业务。','The buyer supplies shops rather than individual shoppers.','批发'),C('wholesale.s2','bulk adjective','The shop ordered wholesale quantities of wheat and paid less per bag.','商店批量订购小麦，每袋支付的价格更低。','wholesale price/quantity; wholesale market','形容与大宗买卖有关的。','The goods are bought in bulk.','批发的'),C('wholesale.s3','extensive change','The new policy caused wholesale changes across the entire welfare system.','新政策在整个福利体系中引发了大规模变革。','wholesale reform/change; wholesale replacement','形容影响范围很大的、几乎全面的。','The change affects nearly every part of the system.','大规模的'),C('wholesale.s4','sell in bulk','The farm wholesales its wheat to bakeries rather than selling each sack to the public.','农场把小麦批发给面包店，而不是把每袋卖给公众。','wholesale goods to shops; wholesale products','动词，指把大量商品出售给商店或其他商家。','The farm sells its crop in bulk to businesses.','批发')],M('The farm wholesaled its wheat by selling one grain at a time to individual visitors.','The farm retailed its wheat by selling small amounts to individual visitors.','Selling single grains to visitors is retailing, not bulk wholesaling.','meaning'),[Q(1,'What kind of business did the wholesaler conduct?','Bulk sales to neighborhood shops','One-at-a-time sales to every passerby','Repairing the shops’ whiteboards','Sense 1 is the trade of selling in quantity to retailers.','context'),Q(2,'Why did the shop order wholesale quantities?','Bulk orders lowered the price per bag','It wanted only one grain','The goods could not be resold','Sense 2 describes bulk buying.','context'),Q(3,'How extensive were the policy changes?','They affected nearly the whole welfare system','They changed one label only','They affected no part of the system','Sense 3 means extensive or nearly total.','context'),Q(4,'Who bought the farm’s wheat?','Bakeries buying in bulk','Individual visitors buying one grain','A whale from the wetland','Sense 4 is selling in large amounts to businesses.','context')]);
P('wholesaler','Wholesaler is wholesale + -er and names a trader who buys goods in bulk and sells them to shops, usually not directly to the public.',C('wholesaler.s1','trade','The wholesaler delivered bulk whiteware to three shops but did not sell appliances to walk-in customers.','批发商向三家商店配送了大宗白色家居用品，但不直接卖给上门顾客。','a food/wholesale wholesaler; supplier to retailers','名词，指大量购货并转售给商店的贸易商。','The trader serves retailers rather than ordinary shoppers.','批发商'),M('The wholesaler bought one cup at a time and sold every item only to individual shoppers.','The retailer bought individual items and sold them to shoppers.','A wholesaler handles bulk trade with shops, not single retail purchases.','meaning'),[Q(1,'Who received the bulk whiteware delivery?','Three shops','Walk-in customers only','The wetland boardwalk','A wholesaler sells to retail shops.','context'),Q(1,'A wholesaler usually…','buys in bulk and sells to shops','sells only one item at a time to the public','writes on a whiteboard','The definition distinguishes wholesale trade from retail.','meaning'),Q(1,'Which phrase is standard?','a wheat wholesaler','a wholesalerly grain','wholesaler to buy one cup','The compound describes a trader specializing in the commodity.','grammar'),Q(1,'Wholesaler is formed from…','wholesale + -er','whole + -less','wharf + -er','The suffix -er names a person who wholesales goods.','word-formation')]);
P('wholesome','Wholesome is whole + -some and describes food that benefits the body or conduct that is morally good and harmless.',[C('wholesome.s1','healthful food','The cook prepared a wholesome soup with beans, vegetables, and whole wheat.','厨师用豆类、蔬菜和全麦做了一锅有益健康的汤。','wholesome food/meal; wholesome diet','形容食物有益身体健康的。','The ingredients make a nourishing meal.','有益健康的'),C('wholesome.s2','moral effect','The film tells a wholesome story about neighbors helping one another after a storm.','这部电影讲述风暴后邻里互助的故事，内容健康向上。','wholesome entertainment; wholesome influence','形容内容或影响积极健康、不易损害品格的。','The story presents constructive behavior.','健康向上的')],M('The wholesome soup was described as nourishing even though it contained only spoiled ingredients.','The spoiled soup was described as unhealthy because its ingredients had gone bad.','Food made from spoiled ingredients is not wholesome.','meaning'),[Q(1,'What made the soup wholesome?','Beans, vegetables, and whole wheat','Spoiled food','A glass of whiskey','Sense 1 concerns food that benefits the body.','context'),Q(2,'Why was the film wholesome?','It showed neighbors helping one another','It encouraged people to harm each other','It hid every consequence of the storm','Sense 2 describes morally positive content.','context'),Q(1,'Which phrase is natural?','wholesome entertainment','wholesomely entertainment','entertainment of wholesomeful','Wholesome is an adjective modifying entertainment.','grammar'),Q(1,'Wholesome is formed from whole +…','-some','-ward','-ness','The suffix forms an adjective meaning beneficial or tending to promote health.','word-formation')]);
P('wholly','Wholly is whole + -ly and means completely, to the full extent, with nothing left out.',C('wholly.s1','completeness','The safety review was wholly independent of the contractor whose work it examined.','安全审查完全独立于被审查工作的承包商。','wholly owned; wholly independent; wholly different','副词，指完全地、全部地，没有遗漏。','The review has no partial connection to the contractor.','完全地'),M('The review was wholly independent because the contractor controlled every conclusion.','The review was not independent because the contractor controlled every conclusion.','A contractor controlling all conclusions contradicts complete independence.','meaning'),[Q(1,'How independent was the safety review?','Completely independent','Only partly connected to the contractor','Not conducted at all','Wholly means to the full extent.','context'),Q(1,'If something is wholly included, it is…','included completely with nothing left out','partly missing','broken into pieces','The adverb means entirely.','meaning'),Q(1,'Which sentence is natural?','The company is wholly owned by its workers.','The company is wholely own by workers.','Wholly the company ownedness.','Wholly modifies owned to mean fully.','grammar'),Q(1,'Wholly is formed from…','whole + -ly','whistle + -ly','wharf + -ly','The suffix -ly makes the adverb meaning completely.','word-formation')]);
})(typeof window!=='undefined'?window:globalThis);
